let currentCountry = null;

/* =========================================================================
   شاشة 1: البداية (Splash)
   ========================================================================= */
function initSplashScreen() {
  document.getElementById('splash-app-name').textContent = APP_CONFIG.nameShort;
  document.getElementById('splash-tagline').textContent = APP_CONFIG.tagline;
  document.getElementById('btn-splash-start').addEventListener('click', () => showScreen('screen-login'));
}

/* =========================================================================
   شاشة 2: تسجيل الدخول (بريد إلكتروني + كلمة سر)
   ========================================================================= */
function initLoginScreen() {
  const phoneInput = document.getElementById('input-login-phone');
  const pwInput = document.getElementById('input-login-password');
  const errorEl = document.getElementById('error-login');
  const btn = document.getElementById('btn-login-submit');

  document.getElementById('btn-login-back').addEventListener('click', () => goBack('screen-splash'));
  document.getElementById('btn-goto-register').addEventListener('click', () => showScreen('screen-register-phone'));
  document.getElementById('btn-forgot-password').addEventListener('click', () => {
    document.getElementById('input-forgot-phone').value = phoneInput.value.trim();
    showScreen('screen-forgot-password');
  });

  async function submitLogin() {
    const phoneRaw = phoneInput.value.trim();
    const password = pwInput.value;
    errorEl.classList.remove('show');
    [document.getElementById('wrap-login-phone'), document.getElementById('wrap-login-password')].forEach(w => w.classList.remove('has-error'));

    if (!phoneRaw || !password) {
      errorEl.textContent = 'يرجى إدخال رقم الجوال وكلمة السر';
      errorEl.classList.add('show');
      return;
    }

    btn.classList.add('loading');
    btn.disabled = true;
    const result = await UbourAuth.signIn(phoneRaw, password);
    btn.classList.remove('loading');
    btn.disabled = false;

    if (!result.ok) {
      if (result.error === 'INVALID_PHONE') {
        errorEl.textContent = 'صيغة رقم الجوال غير صحيحة';
      } else if (result.error === 'RATE_LIMITED') {
        errorEl.textContent = 'محاولات كثيرة، انتظر بضع دقائق ثم حاول مجدداً';
      } else if (result.error === 'SERVICE_UNAVAILABLE') {
        errorEl.textContent = 'الخدمة غير متاحة مؤقتاً، حاول لاحقاً';
      } else {
        errorEl.textContent = 'رقم الجوال أو كلمة السر غير صحيحة';
      }
      errorEl.classList.add('show');
      return;
    }
    showToast(`مرحباً بعودتك إلى ${APP_CONFIG.nameShort} 👋`, 'success');
    await routeUserAfterAuth();
  }

  btn.addEventListener('click', submitLogin);
  pwInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') submitLogin(); });
}

/* =========================================================================
   شاشة 3: التسجيل — الخطوة 1: التحقق من رقم الهاتف
   ========================================================================= */
let _pendingRegPhone = null;
function initRegisterPhoneScreen() {
  const phoneInput = document.getElementById('input-reg-phone');
  const errorEl = document.getElementById('error-reg-phone');
  const btn = document.getElementById('btn-register-phone-continue');

  document.getElementById('btn-register-phone-back').addEventListener('click', () => goBack('screen-login'));

  async function submitRegisterPhone() {
    const raw = phoneInput.value.trim();
    errorEl.classList.remove('show');
    document.getElementById('wrap-reg-phone').classList.remove('has-error');

    const result = UbourAuth.detectPhone(raw);
    if (!result.valid) {
      errorEl.textContent = 'صيغة الرقم غير صحيحة. أدخل رقماً يمنياً (7xxxxxxxx) أو سعودياً (05xxxxxxxx)';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-phone').classList.add('has-error');
      return;
    }

    btn.classList.add('loading');
    btn.disabled = true;
    let exists;
    try { exists = await UbourDB.checkPhoneExists(result.e164); }
    catch (e) {
      btn.classList.remove('loading'); btn.disabled = false;
      errorEl.textContent = (e && e.message === 'RATE_LIMITED') ? 'محاولات كثيرة، انتظر بضع دقائق ثم حاول مجدداً' : 'الخدمة غير متاحة مؤقتاً، حاول لاحقاً';
      errorEl.classList.add('show');
      return;
    }
    btn.classList.remove('loading');
    btn.disabled = false;

    if (exists) {
      errorEl.textContent = 'هذا الرقم مسجّل بالفعل بحساب آخر. جرّب تسجيل الدخول بدلاً من ذلك';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-phone').classList.add('has-error');
      return;
    }

    _pendingRegPhone = raw;
    showScreen('screen-register-account');
  }

  btn.addEventListener('click', submitRegisterPhone);
  phoneInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') submitRegisterPhone(); });
}

/* =========================================================================
   شاشة 4: التسجيل — الخطوة 2: البريد وكلمة السر
   ========================================================================= */
function initRegisterAccountScreen() {
  const emailInput = document.getElementById('input-reg-email');
  const pwInput = document.getElementById('input-reg-password');
  const pwConfirm = document.getElementById('input-reg-password-confirm');
  const strengthBar = document.getElementById('pw-strength-bar');
  const strengthLabel = document.getElementById('pw-strength-label');
  const errorEl = document.getElementById('error-reg-account');
  const btn = document.getElementById('btn-create-account');
  const terms = document.getElementById('checkbox-terms');

  document.getElementById('btn-register-account-back').addEventListener('click', () => goBack('screen-register-phone'));

  pwInput.addEventListener('input', () => {
    const score = UbourAuth.passwordStrength(pwInput.value);
    strengthBar.className = 'pw-strength' + (score === 0 ? '' : score === 1 ? ' weak' : score === 2 ? ' medium' : ' strong');
    const labels = ['أدخل كلمة السر', 'ضعيفة — أضف أرقاماً وحروفاً', 'متوسطة', 'قوية'];
    strengthLabel.textContent = pwInput.value ? labels[score] : '8 أحرف على الأقل، حروف وأرقام';
  });

  async function submitRegisterAccount() {
    errorEl.classList.remove('show');
    [document.getElementById('wrap-reg-email'), document.getElementById('wrap-reg-password'), document.getElementById('wrap-reg-password-confirm')]
      .forEach(w => w.classList.remove('has-error'));

    const email = emailInput.value.trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      errorEl.textContent = 'يرجى إدخال بريد إلكتروني صحيح';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-email').classList.add('has-error');
      return;
    }
    if (pwInput.value.length < 8) {
      errorEl.textContent = 'كلمة السر يجب ألا تقل عن 8 أحرف';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-password').classList.add('has-error');
      return;
    }
    if (pwInput.value !== pwConfirm.value) {
      errorEl.textContent = 'كلمتا السر غير متطابقتين';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-password-confirm').classList.add('has-error');
      return;
    }
    if (!terms.checked) {
      showToast('يرجى الموافقة على الشروط وسياسة الخصوصية للمتابعة', 'error');
      return;
    }

    btn.classList.add('loading');
    btn.disabled = true;
    const result = await UbourAuth.signUp({ phoneRaw: _pendingRegPhone, email, password: pwInput.value });
    btn.classList.remove('loading');
    btn.disabled = false;
    if (result.ok) clearTermsAcceptance();

    if (!result.ok) {
      if (result.error === 'DUPLICATE_PHONE') {
        showToast('هذا الرقم أصبح مسجّلاً للتو من جهاز آخر، يرجى تسجيل الدخول', 'error');
        showScreen('screen-login', { replace: true });
      } else if (result.error === 'DUPLICATE_EMAIL') {
        errorEl.textContent = 'هذا البريد الإلكتروني مسجّل بحساب من قبل';
        errorEl.classList.add('show');
      } else if (result.error === 'RATE_LIMITED') {
        showToast('محاولات كثيرة، انتظر بضع دقائق ثم حاول مجدداً', 'error', 5000);
      } else if (result.error === 'SERVICE_UNAVAILABLE') {
        showToast('الخدمة غير متاحة مؤقتاً، حاول لاحقاً', 'error', 5000);
      } else {
        showToast('حدث خطأ غير متوقع، حاول مرة أخرى', 'error');
      }
      return;
    }

    if (result.needsEmailConfirm) {
      document.getElementById('check-email-address').textContent = email;
      showScreen('screen-check-email', { replace: true });
    } else {
      // بعض مشاريع Supabase تُعطّل اشتراط تأكيد البريد — عندها تبدأ الجلسة فوراً
      showToast('تم إنشاء حسابك بنجاح 🎉', 'success');
      await routeUserAfterAuth();
    }
  }

  btn.addEventListener('click', submitRegisterAccount);
  pwConfirm.addEventListener('keydown', (e) => { if (e.key === 'Enter') submitRegisterAccount(); });

  document.getElementById('btn-check-email-continue').addEventListener('click', () => {
    showScreen('screen-login', { replace: true });
  });
  document.getElementById('btn-check-email-back').addEventListener('click', () => goBack('screen-register-account'));
}

/* =========================================================================
   شاشة: نسيت كلمة السر / تعيين كلمة سر جديدة
   ========================================================================= */
function initForgotPasswordScreen() {
  const phoneInput = document.getElementById('input-forgot-phone');
  const errorEl = document.getElementById('error-forgot-email');
  const btn = document.getElementById('btn-forgot-password-send');

  document.getElementById('btn-forgot-password-back').addEventListener('click', () => goBack('screen-login'));

  btn.addEventListener('click', async () => {
    const phoneRaw = phoneInput.value.trim();
    errorEl.classList.remove('show');
    if (!phoneRaw) {
      errorEl.textContent = 'يرجى إدخال رقم الجوال';
      errorEl.classList.add('show');
      return;
    }
    btn.classList.add('loading');
    btn.disabled = true;
    const result = await UbourAuth.requestPasswordResetByPhone(phoneRaw);
    btn.classList.remove('loading');
    btn.disabled = false;

    if (!result.ok) {
      if (result.error === 'PHONE_NOT_FOUND') {
        errorEl.textContent = 'هذا الرقم غير مسجّل في التطبيق';
      } else if (result.error === 'INVALID_PHONE') {
        errorEl.textContent = 'صيغة رقم الجوال غير صحيحة';
      } else {
        errorEl.textContent = 'تعذّر إرسال رابط الاستعادة، حاول مجدداً';
      }
      errorEl.classList.add('show');
      return;
    }
    showToast('إن كان الرقم مسجّلاً فسيصلك رابط استعادة كلمة السر على بريدك المسجّل', 'success', 5000);
    showScreen('screen-login', { replace: true });
  });
}

function showResetLinkExpired() {
  _recoveryMode = false;
  try { history.replaceState(null, '', window.location.pathname); } catch (e) { /* تجاهل */ }
  showScreen('screen-forgot-password', { replace: true });
  const er = document.getElementById('error-forgot-email');
  if (er) { er.textContent = 'رابط الاستعادة منتهي الصلاحية أو سبق استخدامه. أدخل رقم جوالك لطلب رابط جديد.'; er.classList.add('show'); }
  showToast('رابط الاستعادة غير صالح — اطلب رابطاً جديداً', 'error', 6000);
}

function initResetPasswordScreen() {
  const pwInput = document.getElementById('input-reset-password');
  const pwConfirm = document.getElementById('input-reset-password-confirm');
  const errorEl = document.getElementById('error-reset-password');
  const btn = document.getElementById('btn-reset-password-submit');

  async function leaveRecovery() {
    _recoveryMode = false;
    _currentProfileCache = null;
    try { history.replaceState(null, '', window.location.pathname); } catch (e) { /* تجاهل */ }
    try { await supabaseClient.auth.signOut({ scope: 'global' }); } catch (e) { /* تجاهل */ }
  }

  document.getElementById('btn-reset-password-back').addEventListener('click', async () => {
    await leaveRecovery();
    showScreen('screen-login', { replace: true });
  });

  async function submit() {
    errorEl.classList.remove('show');
    const pw = pwInput.value;
    if (pw.length < 8 || !/\d/.test(pw) || !/[A-Za-z\u0600-\u06FF]/.test(pw)) {
      errorEl.textContent = 'كلمة السر يجب ألا تقل عن 8 خانات وتحتوي حروفاً وأرقاماً';
      errorEl.classList.add('show');
      return;
    }
    if (pw !== pwConfirm.value) {
      errorEl.textContent = 'كلمتا السر غير متطابقتين';
      errorEl.classList.add('show');
      return;
    }
    // لا توجد جلسة استعادة صالحة = الرابط منتهٍ أو مستخدَم سابقاً
    const cur = await supabaseClient.auth.getSession();
    if (!cur || !cur.data || !cur.data.session) { showResetLinkExpired(); return; }

    btn.classList.add('loading');
    btn.disabled = true;
    const result = await UbourAuth.updatePasswordAfterReset(pw);
    btn.classList.remove('loading');
    btn.disabled = false;

    if (!result.ok) {
      const m = String(result.error || '');
      if (/same|different/i.test(m)) errorEl.textContent = 'اختر كلمة سر مختلفة عن كلمة السر السابقة';
      else if (/expired|invalid|session|jwt/i.test(m)) { showResetLinkExpired(); return; }
      else errorEl.textContent = 'تعذّر حفظ كلمة السر، حاول مجدداً';
      errorEl.classList.add('show');
      return;
    }
    pwInput.value = ''; pwConfirm.value = '';
    await leaveRecovery();   // إلغاء كل الجلسات القديمة والحالية — لا دخول تلقائي
    showScreen('screen-login', { replace: true });
    showToast('تم تغيير كلمة السر بنجاح، يرجى تسجيل الدخول بكلمة السر الجديدة', 'success', 6000);
  }
  btn.addEventListener('click', submit);
  pwConfirm.addEventListener('keydown', (e) => { if (e.key === 'Enter') submit(); });
}

/* ---------------- أدوات مشتركة ---------------- */
function currencyLabel(code) {
  const c = APP_CONFIG.currencies.find(x => x.code === code);
  return c ? c.label : code;
}
function bookingStatusLabel(s) {
  return { pending: 'قيد الانتظار', completed: 'مؤكد', cancel_requested: 'ملغي' }[s] || s;
}
function whatsappLink(phone, message) {
  const digits = normalizeDigits(phone || '').replace(/[^\d]/g, '');
  return `https://wa.me/${digits}?text=${encodeURIComponent(message)}`;
}

/* =========================================================================
   v5.2 — أوقات وتواريخ دقيقة، بيانات المكتب، وحالات الحجز
   ========================================================================= */
const _AR_DAYS = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
const _IC_PIN = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22s7-6.2 7-12a7 7 0 0 0-14 0c0 5.8 7 12 7 12z"/><circle cx="12" cy="10" r="2.5"/></svg>';
const _IC_PHONE = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 1.9.7 2.8a2 2 0 0 1-.5 2.1L8.1 9.9a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.8.7a2 2 0 0 1 1.7 2z"/></svg>';

/** '20:30:00' → '8:30 مساءً' (12 ساعة، صباحاً/مساءً صريحة) */
function fmtTime12(t) {
  if (!t) return '';
  const m = /^(\d{1,2}):(\d{2})/.exec(String(t));
  if (!m) return String(t);
  let h = parseInt(m[1], 10);
  const suffix = h >= 12 ? 'مساءً' : 'صباحاً';
  h = h % 12; if (h === 0) h = 12;
  return h + ':' + m[2] + ' ' + suffix;
}
/** '2026-10-10' → 'الجمعة 2026-10-10' */
function fmtDateAr(d) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(d || ''));
  if (!m) return String(d || '');
  const wd = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).getUTCDay();
  return _AR_DAYS[wd] + ' ' + m[1] + '-' + m[2] + '-' + m[3];
}
/** موعد التحرك بالميلي ثانية (توقيت اليمن/السعودية UTC+3) */
function tripDepartureMs(trip) {
  let t = String((trip && trip.trip_time) || '').slice(0, 8);
  if (t.length === 5) t += ':00';
  return new Date(String((trip && trip.trip_date) || '').slice(0, 10) + 'T' + t + '+03:00').getTime();
}
function hoursUntilTrip(trip) { return (tripDepartureMs(trip) - Date.now()) / 3600000; }
/** الفرق بالساعات بين الحضور والتحرك (يدعم عبور منتصف الليل) */
function checkinGapHours(checkin, depart) {
  const toMin = (s) => { const m = /^(\d{1,2}):(\d{2})/.exec(String(s || '')); return m ? (+m[1]) * 60 + (+m[2]) : null; };
  const c = toMin(checkin), d = toMin(depart);
  if (c == null || d == null) return null;
  return ((d - c + 1440) % 1440) / 60;
}
function officeContactNumbers(o) {
  if (!o) return [];
  const list = [o.contact_phone, o.contact_phone2].filter(Boolean);
  return list.length ? list : (o.phone ? [o.phone] : []);
}
/** رقم واتساب المكتب: رقم التواصل الأول إن وُجد، وإلا رقم الحساب */
function officeWaPhone(o) { return (o && (o.contact_phone || o.phone)) || ''; }

function officeAvatarHtml(o, size) {
  const cls = 'office-avatar' + (size === 'lg' ? ' office-avatar-lg' : '');
  if (o && o.logo_url) return '<img class="' + cls + '" src="' + esc(o.logo_url) + '" alt="">';
  const ch = String((o && o.name) || '؟').trim().charAt(0) || '؟';
  return '<span class="' + cls + ' office-avatar-ph">' + esc(ch) + '</span>';
}
/** أزرار "عرض/إخفاء التفاصيل" (الصندوق التالي للزر مباشرة) */
function bindDetailsToggles(root) {
  root.querySelectorAll('[data-toggle-details]').forEach(btn => {
    btn.addEventListener('click', () => {
      const box = btn.nextElementSibling;
      if (!box) return;
      const open = box.classList.toggle('open');
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      btn.textContent = open ? 'إخفاء التفاصيل' : (btn.dataset.label || 'عرض التفاصيل');
    });
  });
}
const PHONES_AFTER_CONFIRM_HINT = '<div class="lc-sub" style="margin-top:6px;">تظهر أرقام التواصل بعد تأكيد المكتب لحجزك — يمكنك التواصل الآن عبر زر واتساب.</div>';
function officeInfoHtml(o, hidePhones) {
  if (!o) return '';
  const nums = hidePhones ? [] : officeContactNumbers(o);
  const loc = o.address ? '<div class="office-line">' + _IC_PIN + '<span>' + esc(o.address) + '</span></div>' : '';
  const ph = nums.length ? '<div class="office-line">' + _IC_PHONE + '<span>' + nums.map(p => '<bdi dir="ltr">' + esc(p) + '</bdi>').join(' • ') + '</span></div>' : '';
  return loc + ph;
}
function tripTimesHtml(t) {
  const dep = '<span class="time-chip time-dep"><b>التحرك</b>' + esc(fmtDateAr(t.trip_date)) + ' — <strong>' + esc(fmtTime12(t.trip_time)) + '</strong></span>';
  const ci = t.checkin_time ? '<span class="time-chip time-checkin"><b>الحضور</b><strong>' + esc(fmtTime12(t.checkin_time)) + '</strong></span>' : '';
  return '<div class="trip-times">' + ci + dep + '</div>';
}
/** نص وصنف شارة الحجز حسب من يشاهدها ('traveler' | 'office') */
function bookingBadge(b, viewer) {
  if (b.status === 'pending') return { text: 'قيد الانتظار', cls: 'status-pending' };
  if (b.status === 'completed') return { text: 'تم تأكيد الحجز ✅', cls: 'status-completed' };
  const byOffice = b.cancelled_by === 'office';
  const rejected = byOffice && b.confirmed_at === null;           // لم يُؤكَّد أصلاً
  let text;
  if (byOffice) {
    if (viewer === 'office') text = rejected ? 'رفضتَه (لم يُؤكَّد)' : 'ألغيتَه';
    else text = rejected ? 'لم يُؤكَّد (رُفض)' : 'ألغاه المكتب';
  } else {
    text = viewer === 'office' ? 'ألغاه المسافر' : 'ألغيتَه';
  }
  return { text, cls: 'status-cancel_requested' };
}
function bookingErrorMessage(e) {
  const m = String((e && e.message) || '');
  if (m.includes('CANCEL_REASON_REQUIRED')) return 'اكتب سبباً واضحاً (3 أحرف على الأقل)';
  if (m.includes('CANCEL_TOO_LATE')) return 'لا يمكن إلغاء الحجز قبل أقل من 12 ساعة من موعد التحرك — تواصل مع المكتب';
  if (m.includes('INVALID_TRANSITION')) return 'لا يمكن تنفيذ هذا الإجراء على الحجز بحالته الحالية';
  if (m.includes('FORBIDDEN')) return 'غير مصرّح لك بتعديل هذا الحجز';
  if (m.includes('REVIEW_NOT_ALLOWED')) return 'يمكن تقييم الحجوزات المؤكَّدة فقط';
  if (m.includes('REVIEW_TOO_EARLY')) return 'يمكن التقييم بعد موعد الرحلة';
  if (/duplicate key|unique/i.test(m)) return 'سبق أن قيّمتَ هذه الرحلة';
  return 'تعذّر تنفيذ العملية، حاول مجدداً';
}
async function doLogout() {
  try { await NotifUI.removePush(); } catch (e) { /* تجاهل */ }
  await UbourAuth.logout();
  _currentProfileCache = null;
  NotifUI.stop();
  screenHistory.length = 0;
  screenHistory.push('screen-login');
  showScreen('screen-login', { replace: true });
  document.getElementById('input-login-phone').value = '';
  document.getElementById('input-login-password').value = '';
  showToast('تم تسجيل الخروج', 'info');
}
function initModals() {
  document.querySelectorAll('.modal-overlay').forEach(overlay => {
    overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModals(); });
    overlay.querySelectorAll('[data-close-modal]').forEach(btn => btn.addEventListener('click', closeModals));
  });
}
function closeModals() {
  document.querySelectorAll('.modal-overlay').forEach(m => m.classList.remove('active'));
}

/* ---------------- التوجيه بعد الدخول/التسجيل حسب الدور ---------------- */
let _recoveryMode = false;   // true أثناء فتح رابط استعادة كلمة السر: يُمنع دخول التطبيق قبل تعيين كلمة سر جديدة

async function routeUserAfterAuth() {
  if (_recoveryMode) { showScreen('screen-reset-password', { replace: true }); return; }
  const profile = await UbourDB.getCurrentProfile();
  if (!profile) { showScreen('screen-login', { replace: true }); return; }

  const isAdmin = await UbourDB.isAdmin(profile.phone);
  if (isAdmin) {
    clearPendingTrip();
    await renderAdminScreen();
    showScreen('screen-admin', { replace: true });
    return;
  }
  if (!profile.role) {
    showScreen('screen-role-select', { replace: true });
    return;
  }
  if (profile.role === 'traveler') {
    await renderTravelerScreen();
    showScreen('screen-traveler', { replace: true });
    renderAdsStrip('ads-strip-traveler');
    consumePendingTrip();
  } else if (profile.role === 'office') {
    clearPendingTrip();
    await renderOfficeScreen();
    showScreen('screen-office', { replace: true });
  } else {
    showScreen('screen-role-select', { replace: true });
  }
}

/* =========================================================================
   شاشة 8: اختيار نوع الحساب
   ========================================================================= */
function initRoleSelectScreen() {
  // لا توجد خطوة "سابقة" منطقية هنا (الحساب أُنشئ بالفعل) — الرجوع يعني
  // تسجيل الخروج والعودة لبداية الدخول، بدل ترك المستخدم في حالة معلّقة
  document.getElementById('btn-role-select-back').addEventListener('click', doLogout);

  document.getElementById('btn-role-traveler').addEventListener('click', async () => {
    const userId = await UbourDB.getCurrentUserId();
    if (!userId) return;
    await UbourDB.setUserRole(userId, 'traveler');
    await renderTravelerScreen();
    showScreen('screen-traveler', { replace: true });
    showToast('مرحباً بك! تصفّح الرحلات المتاحة الآن', 'success');
    renderAdsStrip('ads-strip-traveler');
    consumePendingTrip();
  });
  document.getElementById('btn-role-office').addEventListener('click', () => {
    showScreen('screen-office-setup');
  });
}

/* =========================================================================
   شاشة 9: بيانات المكتب/السائق
   ========================================================================= */
let _selectedAccountType = null;
function initOfficeSetupScreen() {
  document.getElementById('btn-office-setup-back').addEventListener('click', () => goBack('screen-role-select'));

  document.querySelectorAll('#office-account-type-group [data-account-type]').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#office-account-type-group [data-account-type]').forEach(b => {
        b.classList.remove('btn-gold'); b.classList.add('btn-ghost');
      });
      btn.classList.remove('btn-ghost'); btn.classList.add('btn-gold');
      _selectedAccountType = btn.dataset.accountType;
    });
  });

  const btn = document.getElementById('btn-office-setup-submit');
  const errorEl = document.getElementById('error-office-setup');
  btn.addEventListener('click', async () => {
    const name = document.getElementById('input-office-name').value.trim();
    const address = document.getElementById('input-office-address').value.trim();
    errorEl.classList.remove('show');

    if (!_selectedAccountType) {
      errorEl.textContent = 'يرجى اختيار نوع الحساب';
      errorEl.classList.add('show');
      return;
    }
    if (!name) {
      errorEl.textContent = 'يرجى إدخال الاسم';
      errorEl.classList.add('show');
      return;
    }
    const userId = await UbourDB.getCurrentUserId();
    if (!userId) return;

    btn.classList.add('loading'); btn.disabled = true;
    try {
      await UbourDB.createOffice({ userId, name, address, accountType: _selectedAccountType });
      await UbourDB.setUserRole(userId, 'office', name);
      btn.classList.remove('loading'); btn.disabled = false;
      await renderOfficeScreen();
      showScreen('screen-office', { replace: true });
      showToast('تم إنشاء حسابك بنجاح 🎉', 'success');
    } catch (e) {
      btn.classList.remove('loading'); btn.disabled = false;
      showToast('حدث خطأ، حاول مرة أخرى', 'error');
      console.error(e);
    }
  });
}

/* =========================================================================
   شاشة 10: لوحة المسافر
   ========================================================================= */
let _bookingTripId = null;
let _currentProfileCache = null; // يُحدَّث عند كل دخول للوحة لتفادي استعلامات متكررة

async function renderTravelerScreen() {
  const profile = await UbourDB.getCurrentProfile();
  if (!profile) return;
  _currentProfileCache = profile;
  prefetchSupportPhone();
  NotifUI.start(profile.id);
  document.getElementById('traveler-user-phone').textContent = profile.phone;
  document.getElementById('traveler-profile-phone').textContent = profile.phone;

  await renderTravelerTrips();
  await renderTravelerBookings();

  document.querySelectorAll('#screen-traveler .nav-item').forEach(n => n.classList.remove('active'));
  const firstTab = document.querySelector('#screen-traveler .nav-item[data-traveler-tab="search"]');
  if (firstTab) firstTab.classList.add('active');
  document.querySelectorAll('#screen-traveler .home-view').forEach(v => v.classList.add('hidden'));
  document.getElementById('traveler-view-search').classList.remove('hidden');
}

let _tripsCache = [], _ratingsMap = {}, _tripText = '';
const _tripFilters = { time: '', dest: '', minRating: 0, sort: 'soonest', parcels: false };

/** هياكل تحميل رمادية متحركة تظهر قبل وصول القوائم (أول تحميل فقط، لا وميض عند التحديث) */
function skeletonHtml(n) {
  let h = '';
  for (let i = 0; i < n; i++) {
    h += '<div class="skel-card" aria-hidden="true"><div class="skel-row"><span class="skel skel-circle"></span><span class="skel skel-line" style="width:45%"></span></div><span class="skel skel-line" style="width:70%"></span><span class="skel skel-line" style="width:35%"></span></div>';
  }
  return h;
}
function showSkeleton(el, n) {
  if (el && !el.querySelector('.list-card')) el.innerHTML = skeletonHtml(n || 3);
}

async function renderTravelerTrips(filterText) {
  if (filterText != null) _tripText = filterText;
  showSkeleton(document.getElementById('traveler-trips-list'), 3);
  _tripsCache = await UbourDB.getActiveTrips();
  const ids = Array.from(new Set(_tripsCache.map(t => t.office_id)));
  _ratingsMap = ids.length ? await UbourDB.getOfficeRatings(ids) : {};
  drawTravelerTrips();
}

function _tripHour(t) { return parseInt(String(t.trip_time || '').slice(0, 2), 10) || 0; }
function _filtersActive() { return !!(_tripFilters.time || _tripFilters.dest || _tripFilters.minRating > 0 || _tripFilters.sort !== 'soonest' || _tripFilters.parcels); }
function resetTripFilters() { _tripFilters.time = ''; _tripFilters.dest = ''; _tripFilters.minRating = 0; _tripFilters.sort = 'soonest'; _tripFilters.parcels = false; }
function syncFilterUI() {
  document.querySelectorAll('[data-filter-time]').forEach((b) => b.classList.toggle('active', b.dataset.filterTime === _tripFilters.time));
  document.querySelectorAll('[data-filter-parcels]').forEach((b) => b.classList.toggle('active', !!_tripFilters.parcels));
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.value = String(v); };
  set('filter-rating', _tripFilters.minRating); set('filter-sort', _tripFilters.sort);
}
function updateDestinationOptions() {
  const sel = document.getElementById('filter-destination');
  if (!sel) return;
  const dests = Array.from(new Set(_tripsCache.map(t => t.to_place))).sort((a, b) => a.localeCompare(b, 'ar'));
  if (_tripFilters.dest && !dests.includes(_tripFilters.dest)) _tripFilters.dest = '';
  sel.innerHTML = '<option value="">كل الوجهات</option>' + dests.map(d => '<option value="' + esc(d) + '">' + esc(d) + '</option>').join('');
  sel.value = _tripFilters.dest;
}

function drawTravelerTrips() {
  const list = document.getElementById('traveler-trips-list');
  updateDestinationOptions();
  syncFilterUI();
  let trips = _tripsCache.slice();
  const f = (_tripText || '').trim();
  if (f) trips = trips.filter(t => t.from_place.includes(f) || t.to_place.includes(f));
  if (_tripFilters.time === 'am') trips = trips.filter(t => _tripHour(t) < 12);
  if (_tripFilters.time === 'pm') trips = trips.filter(t => _tripHour(t) >= 12);
  if (_tripFilters.dest) trips = trips.filter(t => t.to_place === _tripFilters.dest);
  if (_tripFilters.parcels) trips = trips.filter(t => t.accepts_parcels);
  if (_tripFilters.minRating > 0) trips = trips.filter(t => { const r = _ratingsMap[t.office_id]; return !!r && r.avg >= _tripFilters.minRating; });
  const dep = (t) => tripDepartureMs(t);
  if (_tripFilters.sort === 'rating') {
    trips.sort((a, b) => { const ra = _ratingsMap[a.office_id], rb = _ratingsMap[b.office_id]; return ((rb ? rb.avg : -1) - (ra ? ra.avg : -1)) || (dep(a) - dep(b)); });
  } else {
    trips.sort((a, b) => dep(a) - dep(b));
  }

  trips = trips.filter(isPromoted).concat(trips.filter(t => !isPromoted(t)));   // الرحلات المميزة أولاً
  const summary = document.getElementById('filter-summary');
  if (summary) summary.textContent = _tripsCache.length ? ('النتائج: ' + trips.length + ' من ' + _tripsCache.length + ' رحلة') : '';
  const clearBtn = document.getElementById('btn-clear-filters');
  if (clearBtn) clearBtn.style.display = _filtersActive() ? '' : 'none';

  if (!trips.length) {
    const filtered = _tripsCache.length > 0;
    list.innerHTML = `<div class="empty-state">${ICONS.route}<div class="mt-2">${filtered ? 'لا توجد رحلات مطابقة — جرّب تغيير التصفية' : 'لا توجد رحلات متاحة حالياً'}</div></div>`;
    return;
  }

  list.innerHTML = trips.map(t => {
    const office = t.office || {};
    return `
    <div class="list-card trip-card${isPromoted(t) ? ' promoted' : ''}">
      ${tcHeadHtml(office, t.office_name, _ratingsMap[t.office_id], isPromoted(t) ? '<span class="promo-badge">⭐ مميّزة</span>' : '')}
      ${tcRouteHtml(t)}
      ${tcTimesHtml(t)}
      ${tcInfoHtml(t.seats_available, 'مقعد متاح', t.vehicle_type)}
      ${tcExtraHtml(t)}
      ${t.accepts_parcels ? `<div class="tc-parcels">${ICONS.box}<span><b>يستقبل طرود</b>${t.parcels_note ? ' — ' + esc(t.parcels_note) : ''}</span></div>` : ''}
      <button type="button" class="details-toggle" data-toggle-details aria-expanded="false">عرض التفاصيل</button><div class="trip-details">${officeInfoHtml(office, true)}${PHONES_AFTER_CONFIRM_HINT}${t.accepts_parcels ? `<button type="button" class="parcel-ask-btn" data-parcel-trip="${esc(t.id)}">${ICONS.whatsapp}<span>اسأل عن إرسال طرد</span></button>` : ''}</div>
      <div class="lc-actions">
        <button class="btn btn-primary" data-book-trip="${esc(t.id)}" style="margin-top:0;">حجز مقعد</button>
        <button type="button" class="share-btn" data-share-trip="${esc(t.id)}" aria-label="مشاركة الرحلة">${ICONS.share}</button>
        <button class="whatsapp-btn" data-contact-trip="${esc(t.id)}" style="flex:0 0 auto; width:44px;">${ICONS.whatsapp}</button>
      </div>
    </div>
  `;
  }).join('');
  list.querySelectorAll('[data-book-trip]').forEach(btn => {
    btn.addEventListener('click', () => openBookingModal(btn.dataset.bookTrip));
  });
  bindDetailsToggles(list);
  list.querySelectorAll('[data-contact-trip]').forEach(btn => {
    btn.addEventListener('click', () => {
      const trip = trips.find(x => x.id === btn.dataset.contactTrip);
      const phone = trip && officeWaPhone(trip.office);
      if (!phone) { showToast('رقم تواصل المكتب غير متاح', 'error'); return; }
      const msg = APP_CONFIG.whatsappContactTemplate
        .replace('{trip}', `${trip.from_place} ← ${trip.to_place}`)
        .replace('{date}', `${fmtDateAr(trip.trip_date)} الساعة ${fmtTime12(trip.trip_time)}`);
      openExternal(whatsappLink(phone, msg));
    });
  });
  list.querySelectorAll('[data-share-trip]').forEach(btn => {
    btn.addEventListener('click', () => {
      const t = trips.find(x => x.id === btn.dataset.shareTrip);
      if (t) shareTrip(t, (t.office && t.office.name) || t.office_name || '');
    });
  });
  list.querySelectorAll('[data-parcel-trip]').forEach(btn => {
    btn.addEventListener('click', () => {
      const t = trips.find(x => x.id === btn.dataset.parcelTrip);
      const phone = t && officeWaPhone(t.office);
      if (!phone) { showToast('رقم تواصل المكتب غير متاح', 'error'); return; }
      openExternal(whatsappLink(phone, 'السلام عليكم، أرغب بإرسال طرد مع رحلتكم من ' + t.from_place + ' إلى ' + t.to_place + ' بتاريخ ' + fmtDateAr(t.trip_date) + '. ما الشروط والسعر؟'));
    });
  });
}

/* ---- تنبيه الوجهة + خانة الطرود في نموذج الرحلة ---- */
async function renderRouteAlertsList() {
  const box = document.getElementById('route-alerts-list');
  if (!box) return;
  const items = await UbourDB.getMyRouteAlerts();
  if (!items.length) { box.innerHTML = '<div class="lc-sub" style="padding:10px 0;">لا توجد تنبيهات بعد</div>'; return; }
  box.innerHTML = items.map((a) => '<div class="ra-item"><span>' + esc(a.from_place) + ' ← ' + esc(a.to_place) + '</span><button type="button" class="share-btn" data-delete-alert="' + esc(a.id) + '" aria-label="حذف التنبيه" style="width:36px;height:36px;color:var(--error);">' + ICONS.trash + '</button></div>').join('');
  box.querySelectorAll('[data-delete-alert]').forEach((btn) => btn.addEventListener('click', async () => {
    try { await UbourDB.deleteRouteAlert(btn.dataset.deleteAlert); await renderRouteAlertsList(); }
    catch (e) { showToast('تعذّر حذف التنبيه', 'error'); }
  }));
}
function initNewFeatures() {
  const chk = document.getElementById('input-trip-parcels');
  if (chk) chk.addEventListener('change', () => document.getElementById('wrap-trip-parcels-note').classList.toggle('hidden', !chk.checked));

  const openBtn = document.getElementById('btn-open-route-alerts');
  if (!openBtn) return;
  const fromEl = document.getElementById('input-alert-from'), toEl = document.getElementById('input-alert-to'), er = document.getElementById('error-route-alert');
  openBtn.addEventListener('click', async () => {
    fromEl.value = ''; toEl.value = ''; er.classList.remove('show');
    openOverlay('modal-route-alerts');
    await renderRouteAlertsList();
  });
  document.getElementById('btn-add-route-alert').addEventListener('click', async () => {
    er.classList.remove('show');
    const from = fromEl.value.trim(), to = toEl.value.trim();
    if (!from || !to) { er.textContent = 'اكتب نقطة الانطلاق ونقطة الوصول'; er.classList.add('show'); return; }
    if (from.length > 60 || to.length > 60) { er.textContent = 'الاسم طويل جداً'; er.classList.add('show'); return; }
    try {
      await UbourDB.addRouteAlert(from, to);
      fromEl.value = ''; toEl.value = '';
      await renderRouteAlertsList();
      showToast('سيصلك تنبيه عند نشر رحلة على هذا المسار', 'success', 5000);
    } catch (e) {
      const m = String((e && e.message) || '');
      er.textContent = /ALERTS_LIMIT/.test(m) ? 'وصلت للحد الأقصى (5 تنبيهات) — احذف تنبيهاً لإضافة آخر' : (/duplicate|unique|23505/i.test(m) ? 'هذا التنبيه موجود مسبقاً' : 'تعذّر إضافة التنبيه، حاول مجدداً');
      er.classList.add('show');
    }
  });
}

/* ---- وضع الزائر: تصفّح الرحلات دون تسجيل (الحجز والتواصل بعد الدخول) ---- */
let _guestTrips = [], _guestHighlight = null, _guestText = '';
async function showGuestTrips(highlightId) {
  _guestHighlight = highlightId || null; _guestText = '';
  showScreen('screen-guest', { replace: true });
  const list = document.getElementById('guest-trips-list');
  list.innerHTML = skeletonHtml(3);
  _guestTrips = await UbourDB.getPublicTrips();
  const note = document.getElementById('guest-shared-note');
  if (_guestHighlight) {
    note.textContent = _guestTrips.some((t) => t.id === _guestHighlight) ? '🔗 وصلتك هذه الرحلة — سجّل دخولك الآن لحجزها' : 'هذه الرحلة لم تعد متاحة، لكن تجد أدناه رحلات أخرى';
    note.classList.remove('hidden');
  }
  drawGuestTrips();
}
function drawGuestTrips() {
  const list = document.getElementById('guest-trips-list');
  let trips = _guestTrips.slice();
  const f = _guestText.trim();
  if (f) trips = trips.filter((t) => t.from_place.includes(f) || t.to_place.includes(f));
  trips = trips.filter(isPromoted).concat(trips.filter((t) => !isPromoted(t)));
  if (_guestHighlight) trips = trips.filter((t) => t.id === _guestHighlight).concat(trips.filter((t) => t.id !== _guestHighlight));
  if (!trips.length) { list.innerHTML = `<div class="empty-state">${ICONS.route}<div class="mt-2">لا توجد رحلات متاحة حالياً</div></div>`; return; }
  list.innerHTML = trips.map((t) => {
    const shared = t.id === _guestHighlight;
    const rt = t.rating_count ? { avg: Number(t.rating_avg), count: t.rating_count } : null;
    const extra = (isPromoted(t) ? '<span class="promo-badge">⭐ مميّزة</span>' : '') + (shared ? '<span class="promo-badge" style="background:rgba(22,191,173,.18);color:var(--teal-300);">🔗 الرحلة المشتركة</span>' : '');
    return `
    <div class="list-card trip-card${isPromoted(t) || shared ? ' promoted' : ''}">
      ${tcHeadHtml(t.office, t.office_name, rt, extra)}
      ${tcRouteHtml(t)}
      ${tcTimesHtml(t)}
      ${tcInfoHtml(t.seats_available, 'مقعد متاح', t.vehicle_type)}
      ${tcExtraHtml(t)}
      ${t.accepts_parcels ? `<div class="tc-parcels">${ICONS.box}<span><b>يستقبل طرود</b>${t.parcels_note ? ' — ' + esc(t.parcels_note) : ''}</span></div>` : ''}
      <div class="lc-actions">
        <button class="btn btn-primary" data-guest-book="${esc(t.id)}" style="margin-top:0;">🔒 سجّل دخولك للحجز</button>
        <button type="button" class="share-btn" data-share-trip="${esc(t.id)}" aria-label="مشاركة الرحلة">${ICONS.share}</button>
      </div>
    </div>`;
  }).join('');
  list.querySelectorAll('[data-guest-book]').forEach((btn) => btn.addEventListener('click', () => {
    savePendingTrip(btn.dataset.guestBook);
    openOverlay('modal-login-required');
  }));
  list.querySelectorAll('[data-share-trip]').forEach((btn) => btn.addEventListener('click', () => {
    const t = _guestTrips.find((x) => x.id === btn.dataset.shareTrip);
    if (t) shareTrip(t, t.office_name);
  }));
}
function initGuestMode() {
  const search = document.getElementById('input-guest-search');
  if (search) search.addEventListener('input', () => { _guestText = search.value; drawGuestTrips(); });
  document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-guest-login],[data-guest-register]');
    if (!b) return;
    closeModals();
    showScreen(b.hasAttribute('data-guest-register') ? 'screen-register-phone' : 'screen-login');
  });
}

/* ---- موافقة الشروط: زر «موافق» في صفحتي الشروط والخصوصية يعلّم خانة الموافقة عند العودة ---- */
const TERMS_KEY = 'ubour_terms_accepted';
function termsAcceptedFresh() {
  try { const t = parseInt(localStorage.getItem(TERMS_KEY) || '0', 10); return t > 0 && Date.now() - t < 6 * 3600 * 1000; } catch (e) { return false; }
}
function clearTermsAcceptance() { try { localStorage.removeItem(TERMS_KEY); } catch (e) { /* تجاهل */ } }
function applyTermsAcceptance(silent) {
  const cb = document.getElementById('checkbox-terms');
  if (!cb || cb.checked || !termsAcceptedFresh()) return;
  cb.checked = true;
  if (!silent) showToast('تم تسجيل موافقتك على شروط الاستخدام وسياسة الخصوصية ✔', 'success', 4000);
}
function initTermsAcceptance() {
  window.addEventListener('storage', (e) => { if (e.key === TERMS_KEY) applyTermsAcceptance(false); });
  window.addEventListener('focus', () => applyTermsAcceptance(false));
  document.addEventListener('visibilitychange', () => { if (!document.hidden) applyTermsAcceptance(false); });
  applyTermsAcceptance(true);
}

function initTripFilters() {
  document.querySelectorAll('[data-filter-parcels]').forEach((btn) => btn.addEventListener('click', () => { _tripFilters.parcels = !_tripFilters.parcels; drawTravelerTrips(); }));
  document.querySelectorAll('[data-filter-time]').forEach((btn) => btn.addEventListener('click', () => {
    _tripFilters.time = btn.dataset.filterTime || '';
    drawTravelerTrips();
  }));
  const bind = (id, key, conv) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', () => { _tripFilters[key] = conv(el.value); drawTravelerTrips(); });
  };
  bind('filter-destination', 'dest', (v) => v);
  bind('filter-rating', 'minRating', (v) => Number(v) || 0);
  bind('filter-sort', 'sort', (v) => v || 'soonest');
  const clear = document.getElementById('btn-clear-filters');
  if (clear) clear.addEventListener('click', () => { resetTripFilters(); drawTravelerTrips(); });
}

const _tbCtx = {};   // سياق حجوزات المسافر المعروضة (للأزرار)
async function renderTravelerBookings() {
  const profile = _currentProfileCache || await UbourDB.getCurrentProfile();
  const list = document.getElementById('traveler-bookings-list');
  if (!profile) { list.innerHTML = ''; return; }
  showSkeleton(list, 3);
  const bookings = await UbourDB.getBookingsByTraveler(profile.id);
  if (!bookings.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.box}<div class="mt-2">لا توجد حجوزات بعد</div></div>`;
    return;
  }
  const tripsMap = await UbourDB.getTripsByIds(bookings.map((b) => b.trip_id));
  const officesMap = await UbourDB.getProfilesByIds(Object.values(tripsMap).map((t) => t.office_id));
  const items = bookings.slice().reverse().map((b) => {
    const trip = tripsMap[b.trip_id];
    if (!trip || isPastRetention(trip)) return null;
    return { b, trip, office: officesMap[trip.office_id] || null };
  }).filter(Boolean);
  const ratings = await UbourDB.getOfficeRatings(Array.from(new Set(items.map(x => x.trip.office_id))));
  const myReviews = await UbourDB.getMyReviews();

  list.innerHTML = items.map(({ b, trip, office }) => {
    _tbCtx[b.id] = { b, trip, office };
    const live = b.status === 'pending' || b.status === 'completed';
    const hrs = hoursUntilTrip(trip);
    const canCancel = live && hrs >= 12;
    const tooLate = live && hrs > 0 && hrs < 12;
    const soon = b.status === 'completed' && hrs > 0 && hrs <= 24;
    const departed = b.status === 'completed' && hrs <= 0;
    const badge = bookingBadge(b, 'traveler');
    const review = myReviews[b.id];
    const ci = trip.checkin_time ? ` — الحضور ${esc(fmtTime12(trip.checkin_time))}` : '';
    return `
      <div class="list-card trip-card">
        ${tcHeadHtml(office, trip.office_name, ratings[trip.office_id], `<span class="badge-pill ${badge.cls}">${esc(badge.text)}</span>`)}
        ${tcRouteHtml(trip)}
        ${tcTimesHtml(trip)}
        ${tcInfoHtml(b.seats, 'مقعد محجوز', trip.vehicle_type)}
        ${tcExtraHtml(trip)}
        <button type="button" class="details-toggle" data-toggle-details data-label="تفاصيل المكتب" aria-expanded="false">تفاصيل المكتب</button><div class="trip-details">${officeInfoHtml(office, b.status !== 'completed')}${b.status !== 'completed' && live ? PHONES_AFTER_CONFIRM_HINT : ''}</div>
        ${b.status === 'cancel_requested' ? cancelReasonBoxHtml(b) : ''}
        ${soon && !b.ready_at ? `<div class="remind-box"><span>⏰ رحلتك بعد ${esc(hoursText(hrs))}${ci}. هل أنت مستعد؟</span><button type="button" class="act-btn act-confirm" data-ready-booking="${esc(b.id)}">أنا جاهز ✅</button></div>` : ''}
        ${soon && b.ready_at ? `<div class="remind-box ok">✅ أكّدتَ جاهزيتك للرحلة${ci}</div>` : ''}
        ${tooLate ? `<div class="lc-sub" style="margin-top:6px;">لا يمكن إلغاء الحجز قبل أقل من 12 ساعة من موعد التحرك — تواصل مع المكتب عبر واتساب.</div>` : ''}
        ${departed && review ? `<div class="review-done"><b>تقييمك:</b> <span class="rb-star">${starsText(review.rating)}</span>${review.comment ? `<div class="rv-comment">${esc(review.comment)}</div>` : ''}</div>` : ''}
        <div class="lc-actions lc-actions-wrap">
          ${live ? `<button class="whatsapp-btn" data-contact-office="${esc(b.id)}">${ICONS.whatsapp}تواصل مع المكتب</button>` : ''}
          ${departed && !review ? `<button type="button" class="act-btn act-confirm" data-review-booking="${esc(b.id)}">⭐ قيّم الرحلة</button>` : ''}
          ${canCancel ? `<button class="btn btn-ghost" data-cancel-booking="${esc(b.id)}" style="padding:10px; font-size:13px; color:var(--error); border-color:var(--error); flex:1;">إلغاء الحجز</button>` : ''}
        </div>
      </div>`;
  }).join('');

  bindDetailsToggles(list);
  list.querySelectorAll('[data-cancel-booking]').forEach(btn => {
    btn.addEventListener('click', () => {
      const ctx = _tbCtx[btn.dataset.cancelBooking];
      if (ctx && hoursUntilTrip(ctx.trip) < 12) { showToast(bookingErrorMessage({ message: 'CANCEL_TOO_LATE' }), 'error', 5000); return; }
      openCancelModal(btn.dataset.cancelBooking, 'traveler');
    });
  });
  list.querySelectorAll('[data-contact-office]').forEach(btn => {
    btn.addEventListener('click', () => {
      const ctx = _tbCtx[btn.dataset.contactOffice];
      const phone = ctx && officeWaPhone(ctx.office);
      if (!phone) { showToast('رقم تواصل المكتب غير متاح', 'error'); return; }
      const msg = `مرحباً، أنا ${ctx.b.traveler_name} بخصوص حجزي لرحلة ${ctx.trip.from_place} ← ${ctx.trip.to_place} يوم ${fmtDateAr(ctx.trip.trip_date)} الساعة ${fmtTime12(ctx.trip.trip_time)}.`;
      openExternal(whatsappLink(phone, msg));
    });
  });
  list.querySelectorAll('[data-ready-booking]').forEach(btn => {
    btn.addEventListener('click', async () => {
      if (btn.disabled) return;
      btn.disabled = true;
      try { await UbourDB.markBookingReady(btn.dataset.readyBooking); showToast('تم إبلاغ المكتب بجاهزيتك', 'success'); }
      catch (e) { showToast(bookingErrorMessage(e), 'error'); console.error(e); }
      await renderTravelerBookings();
    });
  });
  list.querySelectorAll('[data-review-booking]').forEach(btn => {
    btn.addEventListener('click', () => {
      const ctx = _tbCtx[btn.dataset.reviewBooking];
      openReviewModal(btn.dataset.reviewBooking, (ctx && ctx.office && ctx.office.name) || (ctx && ctx.trip.office_name) || '');
    });
  });
}

async function openBookingModal(tripId) {
  const trip = await UbourDB.getTripById(tripId);
  if (!trip) return;
  _bookingTripId = tripId;
  const office = await UbourDB.getProfileById(trip.office_id);
  const head = document.getElementById('book-trip-office');
  if (head) {
    const rt = (await UbourDB.getOfficeRatings([trip.office_id]))[trip.office_id];
    head.innerHTML = `<div class="office-head">${officeAvatarHtml(office || { name: trip.office_name }, 'lg')}<div class="office-meta"><div class="office-name">${esc((office && office.name) || trip.office_name)}</div>${ratingBadgeHtml(rt)}${officeInfoHtml(office, true)}</div></div>`;
  }
  document.getElementById('book-trip-summary').innerHTML =
    `<div class="lc-route" style="margin-bottom:8px;">${esc(trip.from_place)} ← ${esc(trip.to_place)}</div>` +
    tripTimesHtml(trip) +
    `<div style="margin-top:8px;">${esc(trip.price)} ${currencyLabel(trip.currency)} للمقعد الواحد</div>`;
  const seatsInput = document.getElementById('input-booker-seats');
  seatsInput.value = 1;
  seatsInput.max = trip.seats_available;
  document.getElementById('modal-book-trip').classList.add('active');
}

/* ---------------- نافذة إلغاء/رفض الحجز أو إلغاء الرحلة (مشتركة) ---------------- */
let _cancelContext = null; // { id, initiator: 'traveler'|'office', type: 'booking'|'trip', mode }
const CANCEL_TEXTS = {
  traveler: { title: 'إلغاء الحجز', label: 'سبب الإلغاء (إلزامي)', ph: 'اكتب سبب إلغاء الحجز...', btn: 'تأكيد الإلغاء' },
  reject: { title: 'عدم تأكيد الحجز', label: 'سبب عدم التأكيد (سيصل للمسافر)', ph: 'مثال: لا تتوفر مقاعد مناسبة في هذا الموعد', btn: 'تأكيد عدم القبول وإبلاغ المسافر' },
  'cancel-confirmed': { title: 'إلغاء حجز مؤكَّد', label: 'سبب الإلغاء (سيصل للمسافر)', ph: 'اكتب سبب الإلغاء...', btn: 'تأكيد الإلغاء وإبلاغ المسافر' },
  trip: { title: 'إلغاء الرحلة', label: 'سبب إلغاء الرحلة', ph: 'اكتب سبب الإلغاء هنا...', btn: 'تأكيد الإلغاء وإرسال السبب' }
};
function openCancelModal(id, initiator, type, mode) {
  const kind = (type || 'booking') === 'trip' ? 'trip' : (mode || (initiator === 'office' ? 'cancel-confirmed' : 'traveler'));
  _cancelContext = { id, initiator, type: type || 'booking', mode: kind };
  const tx = CANCEL_TEXTS[kind] || CANCEL_TEXTS.traveler;
  const input = document.getElementById('input-cancel-reason');
  input.value = '';
  input.placeholder = tx.ph;
  const label = document.querySelector('label[for="input-cancel-reason"]');
  if (label) label.textContent = tx.label;
  const btnLabel = document.querySelector('#btn-submit-cancel .btn-label');
  if (btnLabel) btnLabel.textContent = tx.btn;
  document.getElementById('cancel-modal-title').textContent = tx.title;
  document.getElementById('modal-cancel-booking').classList.add('active');
}
function initCancelModal() {
  document.getElementById('btn-submit-cancel').addEventListener('click', async () => {
    if (!_cancelContext) return;
    const reason = document.getElementById('input-cancel-reason').value.trim();
    if (reason.length < 3) { showToast('اكتب سبباً واضحاً (3 أحرف على الأقل)', 'error'); return; }

    const { id, initiator, type, mode } = _cancelContext;

    if (type === 'trip') {
      // إلغاء رحلة كاملة: تُلغى كل الحجوزات المرتبطة بها تلقائياً بنفس السبب
      const allBookings = await UbourDB.getAllBookings();
      const bookingsBefore = allBookings.filter(b => b.trip_id === id && b.status !== 'cancel_requested');
      let trip;
      try { trip = await UbourDB.cancelTrip(id, reason); }
      catch (e) { showToast(bookingErrorMessage(e), 'error'); console.error(e); return; }
      if (!trip) return;

      // إخطار أول مسافر حجز عبر واتساب (المتصفحات تمنع فتح أكثر من نافذة منبثقة تلقائياً لكل نقرة)
      if (bookingsBefore.length > 0) {
        const first = bookingsBefore[0];
        const msg = APP_CONFIG.whatsappCancelToTravelerTemplate
          .replace('{trip}', `${trip.from_place} ← ${trip.to_place}`).replace('{date}', fmtDateAr(trip.trip_date)).replace('{reason}', reason);
        openExternal(whatsappLink(first.traveler_phone, msg));
      }
      const extra = bookingsBefore.length > 1 ? ` (يرجى إخطار باقي ${bookingsBefore.length - 1} مسافراً يدوياً عبر واتساب)` : '';
      showToast(`تم إلغاء الرحلة وكل حجوزاتها${extra}`, 'info', 6000);

      const profile = await UbourDB.getCurrentProfile();
      if (profile) { await renderOfficeTrips(profile); await renderOfficeRequests(profile); }
    } else {
      let booking;
      try { booking = await UbourDB.cancelBooking(id, reason, initiator); }
      catch (e) { showToast(bookingErrorMessage(e), 'error', 5000); console.error(e); return; }
      if (!booking) return;
      const trip = await UbourDB.getTripById(booking.trip_id);
      const office = trip && await UbourDB.getProfileById(trip.office_id);
      const tripText = trip ? `${trip.from_place} ← ${trip.to_place}` : '';
      const dateText = trip ? `${fmtDateAr(trip.trip_date)} الساعة ${fmtTime12(trip.trip_time)}` : '';

      if (initiator === 'traveler') {
        const phone = officeWaPhone(office);
        if (phone) {
          const msg = APP_CONFIG.whatsappCancelToOfficeTemplate
            .replace('{trip}', tripText).replace('{date}', dateText).replace('{reason}', reason);
          openExternal(whatsappLink(phone, `${booking.traveler_name ? 'الاسم: ' + booking.traveler_name + '\n' : ''}${msg}`));
        }
        await renderTravelerBookings();
        await renderTravelerTrips();
        showToast('تم إلغاء حجزك وأُعيد المقعد للمتاح', 'info');
      } else if (initiator === 'office') {
        const tpl = mode === 'reject' ? APP_CONFIG.whatsappRejectToTravelerTemplate : APP_CONFIG.whatsappCancelToTravelerTemplate;
        const officeName = (_currentProfileCache && _currentProfileCache.name) || (office && office.name) || '';
        const msg = `مرحباً ${booking.traveler_name || ''}، معك ${officeName}.\n` +
          tpl.replace('{trip}', tripText).replace('{date}', dateText).replace('{reason}', reason);
        openExternal(whatsappLink(booking.traveler_phone, msg));
        const profile = await UbourDB.getCurrentProfile();
        if (profile) { await renderOfficeRequests(profile); await renderOfficeTrips(profile); }
        showToast(mode === 'reject' ? 'تم رفض الحجز وإبلاغ المسافر، والمقعد عاد متاحاً' : 'تم إلغاء الحجز وأُعيد المقعد للمتاح', 'info', 5000);
      }
    }

    closeModals();
    _cancelContext = null;
  });
}



/* =========================================================================
   v5.3 — التقييم، التنبيهات، التصفية، الإحصائيات (مساعدات)
   ========================================================================= */
function _isMissingDbObject(error) {
  const m = String((error && error.message) || '');
  return !!error && (error.code === '42883' || error.code === '42P01' || error.code === 'PGRST202' || error.code === 'PGRST205' || /does not exist|schema cache|Could not find/i.test(m));
}
function starsText(n) {
  const full = Math.max(0, Math.min(5, Math.round(Number(n) || 0)));
  return '★'.repeat(full) + '☆'.repeat(5 - full);
}
/** نجوم التقييم (تعبئة جزئية بالنسبة المئوية) + الرقم وعدد المقيّمين تحتها */
function starsHtml(rt) {
  const has = !!(rt && rt.count);
  const avg = has ? Math.max(0, Math.min(5, Number(rt.avg) || 0)) : 0;
  const label = has ? ('التقييم ' + avg.toFixed(1) + ' من 5') : 'مكتب جديد بلا تقييم بعد';
  return '<div class="tc-rating" role="img" aria-label="' + label + '"><span class="tc-stars" style="--p:' + Math.round(avg / 5 * 100) + '%" aria-hidden="true">★★★★★</span>'
    + (has ? '<span class="tc-rate-num"><b>' + esc(avg.toFixed(1)) + '</b> (' + esc(rt.count) + ')</span>' : '<span class="tc-rate-num tc-new">جديد</span>') + '</div>';
}
function verifiedBadgeHtml(o) { return (o && o.featured) ? '<span class="verified-badge" title="مكتب موثّق">✔ موثّق</span>' : ''; }
function tcHeadHtml(office, fallbackName, rt, extra) {
  const o = office || {};
  const name = o.name || fallbackName || '';
  return '<div class="tc-head"><div class="tc-logo">' + officeAvatarHtml({ name: name, logo_url: o.logo_url }, 'lg') + starsHtml(rt) + '</div>'
    + '<div class="tc-namebox"><div class="tc-name">' + esc(name) + '</div>' + verifiedBadgeHtml(o) + (extra || '') + '</div></div>';
}
function tcRouteHtml(t) {
  return '<div class="tc-row"><div class="tc-route">' + ICONS.route + '<span>' + esc(t.from_place) + '</span>' + ICONS.chevron + '<span>' + esc(t.to_place) + '</span></div>'
    + '<div class="tc-price"><strong>' + esc(fmtPrice(t.price)) + '</strong><small>' + currencyLabel(t.currency) + '</small></div></div>';
}
function tcTimesHtml(t) {
  const ci = t.checkin_time ? '<div class="tc-tile tc-time-ci"><small>الحضور</small><b>' + esc(fmtTime12(t.checkin_time)) + '</b></div>' : '';
  return '<div class="tc-times' + (ci ? '' : ' single') + '"><div class="tc-tile tc-time-dep"><small>التحرك</small><b>' + esc(fmtDateAr(t.trip_date)) + '</b><span>' + esc(fmtTime12(t.trip_time)) + '</span></div>' + ci + '</div>';
}
function tcInfoHtml(count, text, vehicle) {
  return '<div class="tc-info' + (vehicle ? '' : ' single') + '"><div class="tc-tile tc-seats">' + ICONS.users + '<div class="tc-seats-col"><span class="tc-seats-num">' + esc(count) + '</span><span class="tc-seats-txt">' + esc(text) + '</span></div></div>'
    + (vehicle ? '<div class="tc-tile tc-veh"><small>نوع السيارة</small><b>' + esc(vehicle) + '</b></div>' : '') + '</div>';
}

/** تفاصيل اختيارية يكتبها المكتب: وصف مميز + مسار + مميزات (لا أرقام هواتف هنا إطلاقاً) */
function tcExtraHtml(t) {
  if (!t) return '';
  const tag = String(t.trip_title || '').trim();
  const route = String(t.route_details || '').trim();
  const am = String(t.amenities || '').split(/[,،]/).map((x) => x.trim()).filter(Boolean).slice(0, 10);
  if (!tag && !route && !am.length) return '';
  return '<div class="tc-extra">'
    + (tag ? '<span class="tc-tag">🏷️ ' + esc(tag) + '</span>' : '')
    + (route ? '<div class="tc-route-details"><span aria-hidden="true">🛣️</span><span><b>المسار:</b> ' + esc(route) + '</span></div>' : '')
    + (am.length ? '<div class="tc-amen">' + am.map((a) => '<span class="tc-amen-chip">' + esc(a) + '</span>').join('') + '</div>' : '')
    + '</div>';
}

/* ---- مشاركة الرحلة عبر واتساب + رابط مباشر يفتح حجزها ---- */
const PENDING_TRIP_KEY = 'ubour_pending_trip';
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
function tripShareText(t, officeName) {
  const link = window.location.origin + '/?trip=' + encodeURIComponent(t.id);
  const title = String(t.trip_title || '').trim();
  const route = String(t.route_details || '').trim();
  const am = String(t.amenities || '').split(/[,،]/).map((x) => x.trim()).filter(Boolean).join('، ');
  return '🚌 *' + (officeName || 'رحلة جديدة') + '*\n'
    + (title ? '🏷️ *نوع الرحلة:* ' + title + '\n' : '')
    + '📍 *الرحلة:* ' + t.from_place + ' ⬅️ ' + t.to_place + '\n'
    + '📅 *التاريخ والوقت:* ' + fmtDateAr(t.trip_date) + ' — ' + fmtTime12(t.trip_time) + '\n'
    + (route ? '🛣️ *المسار:* ' + route + '\n' : '')
    + '💰 *السعر:* ' + fmtPrice(t.price) + ' ' + currencyLabel(t.currency) + '\n'
    + '🪑 *المقاعد المتاحة:* ' + t.seats_available + '\n'
    + (am ? '✨ *المميزات:* ' + am + '\n' : '')
    + (t.accepts_parcels ? '📦 تستقبل طرود\n' : '')
    + '\n🔗 *رابط التفاصيل والحجز:*\n' + link;
}
/** على الجوال: قائمة المشاركة الأصلية للنظام (يختار المستخدم أي واتساب: العادي أو الأعمال) — وإلا رابط wa.me القياسي */
function shareTrip(t, officeName) {
  const text = tripShareText(t, officeName);
  const waUrl = 'https://wa.me/?text=' + encodeURIComponent(text);
  if (navigator.share && /Android|iPhone|iPad|iPod/i.test(navigator.userAgent || '')) {
    navigator.share({ text: text }).catch((e) => { if (!e || e.name !== 'AbortError') openExternal(waUrl); });
    return;
  }
  openExternal(waUrl);
}
function savePendingTrip(id) { try { localStorage.setItem(PENDING_TRIP_KEY, JSON.stringify({ id: id, ts: Date.now() })); } catch (e) { /* تجاهل */ } }
function readPendingTrip() {
  try {
    const o = JSON.parse(localStorage.getItem(PENDING_TRIP_KEY) || 'null');
    if (o && UUID_RE.test(o.id) && Date.now() - o.ts < 24 * 3600 * 1000) return o.id;
  } catch (e) { /* تجاهل */ }
  return null;
}
function clearPendingTrip() { try { localStorage.removeItem(PENDING_TRIP_KEY); } catch (e) { /* تجاهل */ } }
function captureSharedTripFromUrl() {
  try {
    const p = new URLSearchParams(window.location.search).get('trip');
    if (p && UUID_RE.test(p)) {
      savePendingTrip(p);
      history.replaceState(null, '', window.location.pathname + window.location.hash);
      return true;
    }
  } catch (e) { /* تجاهل */ }
  return false;
}
async function consumePendingTrip() {
  const id = readPendingTrip();
  if (!id) return;
  clearPendingTrip();
  const n = document.getElementById('shared-trip-notice'); if (n) n.classList.add('hidden');
  if (_tripsCache.some((t) => t.id === id)) setTimeout(() => openBookingModal(id), 350);
  else showToast('هذه الرحلة لم تعد متاحة أو اكتمل حجزها', 'info', 6000);
}

/* ---- الإعلانات (تُنشأ من لوحة الإدارة وتظهر لكل المستخدمين) ---- */
let _adsCache = { ts: 0, items: [] };
function _safeUrl(u, httpsOnly) {
  try { const x = new URL(String(u || '').trim()); if (x.protocol === 'https:' || (!httpsOnly && x.protocol === 'http:')) return x.href; } catch (e) { /* تجاهل */ }
  return '';
}
async function renderAdsStrip(id) {
  const box = document.getElementById(id);
  if (!box) return;
  try {
    if (Date.now() - _adsCache.ts > 300000) _adsCache = { ts: Date.now(), items: (await UbourDB.getAllAds()).filter((a) => !a.expires_at || new Date(a.expires_at) > new Date()).slice(0, 10) };
    const ads = _adsCache.items;
    if (!ads.length) { box.classList.add('hidden'); box.innerHTML = ''; return; }
    box.innerHTML = ads.map((a) => {
      const img = _safeUrl(a.image_url, true), link = _safeUrl(a.link_url, false);
      const inner = (img ? '<img class="ad-img" loading="lazy" alt="" src="' + esc(img) + '">' : '')
        + '<div class="ad-body"><span class="ad-tag">إعلان</span><div class="ad-title">' + esc(a.title) + '</div>'
        + (a.description ? '<div class="ad-desc">' + esc(a.description) + '</div>' : '') + '</div>';
      return link ? '<a class="ad-card" href="' + esc(link) + '" target="_blank" rel="noopener noreferrer">' + inner + '</a>' : '<div class="ad-card">' + inner + '</div>';
    }).join('');
    box.classList.toggle('single', ads.length === 1);
    box.classList.remove('hidden');
  } catch (e) { box.classList.add('hidden'); }
}

function fmtPrice(p) {
  const n = Number(p);
  return isFinite(n) ? n.toLocaleString('en-US') : String(p);
}
function ratingBadgeHtml(rt) {
  if (!rt || !rt.count) return '<span class="rating-badge rb-new">جديد — بلا تقييم بعد</span>';
  return '<span class="rating-badge"><span class="rb-star">★</span><b>' + esc(rt.avg.toFixed(1)) + '</b><small>(' + esc(rt.count) + ')</small></span>';
}
/** صندوق سبب الإلغاء/الرفض الواضح للمسافر في «حجوزاتي» */
function cancelReasonBoxHtml(b) {
  const reason = b.cancel_reason ? esc(b.cancel_reason) : 'لم يُذكر سبب';
  if (b.cancelled_by === 'office') {
    const rejected = b.confirmed_at === null;      // لم يُؤكَّد أصلاً = رفض
    const title = rejected ? '❌ لم يؤكّد المكتب حجزك (تم الرفض)' : '⚠️ ألغى المكتب حجزك المؤكَّد';
    return '<div class="reason-box reject"><div class="rb-title">' + title + '</div><div class="rb-text"><b>السبب:</b> ' + reason + '</div></div>';
  }
  return '<div class="reason-box"><div class="rb-title">ألغيتَ هذا الحجز</div><div class="rb-text"><b>السبب:</b> ' + reason + '</div></div>';
}
function hoursText(h) {
  if (h < 1) return 'أقل من ساعة';
  const r = Math.round(h);
  return r === 1 ? 'ساعة واحدة' : r + ' ساعة';
}

/* ---- v5.2: واتساب الدعم (مسافر / مكتب / سائق) ---- */
let _supportPhone = null;
async function prefetchSupportPhone() {
  try { _supportPhone = (await UbourDB.getPrimaryManagerPhone()) || _supportPhone; } catch (e) { /* تجاهل */ }
}
function initSupportWhatsApp() {
  document.querySelectorAll('[data-support-whatsapp]').forEach((btn) => {
    if (!btn.querySelector('svg')) btn.insertAdjacentHTML('afterbegin', ICONS.whatsapp);
    btn.addEventListener('click', async () => {
      const profile = _currentProfileCache || await UbourDB.getCurrentProfile();
      const phone = _supportPhone || await UbourDB.getPrimaryManagerPhone();
      if (!phone) { showToast('رقم الدعم غير متاح حالياً، أرسل رسالتك من الأسفل وسنردّ عليك', 'error', 5000); return; }
      _supportPhone = phone;
      const role = profile && profile.role === 'office' ? (profile.account_type === 'driver' ? 'سائق' : 'مكتب') : 'مسافر';
      const who = profile && profile.name ? `${profile.name} (${role})` : role;
      const msg = `السلام عليكم ورحمة الله 🌹\nأنا ${who} من تطبيق ${APP_CONFIG.nameShort}.\nيسعدني التواصل معكم بخصوص:\n`;
      openExternal(whatsappLink(phone, msg));
    });
  });
}

function initTravelerScreen() {
  document.querySelectorAll('#screen-traveler .nav-item').forEach(item => {
    item.addEventListener('click', () => {
      document.querySelectorAll('#screen-traveler .nav-item').forEach(n => n.classList.remove('active'));
      item.classList.add('active');
      document.querySelectorAll('#screen-traveler .home-view').forEach(v => v.classList.add('hidden'));
      document.getElementById('traveler-view-' + item.dataset.travelerTab).classList.remove('hidden');
    });
  });

  document.getElementById('input-trip-search').addEventListener('input', (e) => renderTravelerTrips(e.target.value));

  document.getElementById('btn-support-send').addEventListener('click', async () => {
    const msgInput = document.getElementById('input-support-message');
    const msg = msgInput.value.trim();
    if (!msg) { showToast('اكتب رسالتك أولاً', 'error'); return; }
    const profile = await UbourDB.getCurrentProfile();
    if (!profile) return;
    await UbourDB.createSupportMessage({ fromId: profile.id, fromName: profile.name || profile.phone, fromPhone: profile.phone, message: msg });
    msgInput.value = '';
    showToast('تم إرسال رسالتك للدعم الفني', 'success');
  });

  document.getElementById('btn-traveler-logout').addEventListener('click', doLogout);
  initSupportWhatsApp();   // يربط زر واتساب الدعم في شاشتي المسافر والمكتب/السائق
  initTripFilters();
  initNewFeatures();
  initGuestMode();
  initTermsAcceptance();
  initReviewModal();
  NotifUI.bindBells();

  document.getElementById('btn-confirm-booking-whatsapp').addEventListener('click', async () => {
    const trip = await UbourDB.getTripById(_bookingTripId);
    if (!trip) return;
    const name = document.getElementById('input-booker-name').value.trim();
    const seats = parseInt(normalizeDigits(document.getElementById('input-booker-seats').value), 10) || 0;

    if (!name) { showToast('يرجى إدخال اسمك', 'error'); return; }
    if (seats < 1 || seats > trip.seats_available) { showToast('عدد مقاعد غير صالح', 'error'); return; }

    const profile = await UbourDB.getCurrentProfile();
    if (!profile) return;
    try {
      await UbourDB.createBooking({ tripId: trip.id, travelerId: profile.id, travelerName: name, travelerPhone: profile.phone, seats });
    } catch (err) {
      const m = (err && err.message) || '';
      showToast(m.includes('NOT_ENOUGH_SEATS') ? 'عذراً، لم تعد المقاعد المطلوبة متاحة' : m.includes('TRIP_NOT_ACTIVE') ? 'هذه الرحلة لم تعد متاحة للحجز' : m.includes('TOO_MANY_OPEN_BOOKINGS') ? 'لديك حجوزات مفتوحة كثيرة، أكمل أو ألغِ بعضها أولاً' : m.includes('PHONE_REQUIRED') ? 'رقم هاتفك غير مكتمل في حسابك، تواصل مع الدعم' : 'تعذّر إتمام الحجز، حاول مرة أخرى', 'error');
      closeModals();
      await renderTravelerTrips();
      return;
    }

    const office = await UbourDB.getProfileById(trip.office_id);
    const msg = APP_CONFIG.whatsappBookingTemplate
      .replace('{trip}', `${trip.from_place} ← ${trip.to_place} يوم ${fmtDateAr(trip.trip_date)} الساعة ${fmtTime12(trip.trip_time)}`)
      .replace('{seats}', seats)
      .replace('{name}', name);
    const officePhone = officeWaPhone(office);
    if (officePhone) openExternal(whatsappLink(officePhone, msg));

    closeModals();
    await renderTravelerTrips();
    await renderTravelerBookings();
    showToast('تم تسجيل حجزك، أكمل التواصل عبر واتساب مع المكتب', 'success');
  });
}

/* =========================================================================
   شاشة 11: لوحة المكتب/السائق
   ========================================================================= */
async function renderOfficeScreen() {
  const office = await UbourDB.getCurrentProfile();
  if (!office) return;
  _currentProfileCache = office;
  prefetchSupportPhone();
  NotifUI.start(office.id);
  renderOfficeStats(office);

  document.getElementById('office-user-name').innerHTML = esc(office.name) + (office.featured ? ' <span class="verified-badge">✔ موثّق</span>' : '');
  document.getElementById('office-profile-phone').textContent = office.phone;
  document.getElementById('office-profile-address').textContent = office.address || '—';
  const days = UbourDB.daysRemaining(office);
  const subActive = office.subscription_active && days > 0;
  document.getElementById('office-profile-subscription').textContent =
    office.is_disabled ? 'معطّل — راجع الإدارة' : (subActive ? `فعّال (${days} يوم متبقي)` : 'منتهي');
  document.getElementById('subscription-renew-box').classList.toggle('hidden', subActive || !!office.is_disabled);

  // رسالة حالة الحساب أعلى كل صفحات المكتب/السائق: معطّل من الإدارة أو منتهي الاشتراك
  const banner = document.getElementById('office-status-banner');
  if (office.is_disabled || !subActive) {
    document.getElementById('office-status-title').textContent = office.is_disabled ? 'تم تعطيل حسابك' : 'انتهى اشتراكك';
    document.getElementById('office-status-text').textContent = office.is_disabled
      ? 'رحلاتك غير ظاهرة للمسافرين ولا يمكنك نشر رحلات جديدة. يرجى مراجعة الإدارة لمعرفة السبب وإعادة تفعيل الحساب.'
      : 'رحلاتك لن تظهر للمسافرين ولا يمكنك نشر رحلات جديدة. يرجى مراجعة الإدارة لتجديد الاشتراك.';
    banner.classList.remove('hidden');
  } else {
    banner.classList.add('hidden');
  }

  document.getElementById('input-office-edit-name').value = office.name || '';
  document.getElementById('input-office-edit-location').value = office.address || '';
  document.getElementById('input-office-edit-phone1').value = office.contact_phone || '';
  document.getElementById('input-office-edit-phone2').value = office.contact_phone2 || '';
  renderOfficeContactRows(office);
  const preview = document.getElementById('office-logo-preview');
  const placeholder = document.getElementById('office-logo-picker-placeholder');
  if (office.logo_url) {
    preview.src = office.logo_url;
    preview.classList.remove('hidden');
    placeholder.classList.add('hidden');
  } else {
    preview.classList.add('hidden');
    placeholder.classList.remove('hidden');
  }
  renderOfficeAvatar(office);

  await renderOfficeRequests(office);
  await renderOfficeTrips(office);

  document.querySelectorAll('#screen-office .nav-item').forEach(n => n.classList.remove('active'));
  const firstTab = document.querySelector('#screen-office .nav-item[data-office-tab="requests"]');
  if (firstTab) firstTab.classList.add('active');
  document.querySelectorAll('#screen-office .home-view').forEach(v => v.classList.add('hidden'));
  document.getElementById('office-view-requests').classList.remove('hidden');
}

function renderOfficeContactRows(office) {
  const nums = [office.contact_phone, office.contact_phone2].filter(Boolean);
  const el = document.getElementById('office-profile-contacts');
  if (el) el.textContent = nums.length ? nums.join(' • ') : '—';
  const addr = document.getElementById('office-profile-address');
  if (addr) addr.textContent = office.address || '—';
}

function renderOfficeAvatar(office) {
  const wrap = document.getElementById('office-avatar-wrap');
  if (office.logo_url) {
    wrap.innerHTML = `<img src="${esc(office.logo_url)}" alt="شعار المكتب" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">`;
  } else {
    wrap.innerHTML = `<span id="icon-office-avatar">${ICONS.userCircle}</span>`;
  }
}

/* ---- بحث المكاتب/السائقين في رحلاتهم وطلباتهم ---- */
const _officeSearch = { trips: '', requests: '', admin: '' };
const RETENTION_DAYS = 10;   // لا تُعرض رحلة/حجز مضى على موعدها أكثر من 10 أيام (والأرشفة الفعلية في قاعدة البيانات)
function isPastRetention(t) {
  if (!t || !t.trip_date) return false;
  const ts = Date.parse(t.trip_date + 'T' + String(t.trip_time || '00:00:00').slice(0, 8) + '+03:00');
  return !isNaN(ts) && ts < Date.now() - RETENTION_DAYS * 86400000;
}
let _officeTripsCache = null, _officeReqCache = null;
function _norm(x) { return String(x == null ? '' : x).toLowerCase(); }
function ensureOfficeSearch(list, key, placeholder, redraw) {
  const id = 'office-search-' + key;
  if (document.getElementById(id)) return;
  const box = document.createElement('div');
  box.id = id; box.className = 'office-search';
  box.innerHTML = '<div class="input-wrap"><input type="search" autocomplete="off" maxlength="60" placeholder="' + placeholder + '"></div>';
  list.parentNode.insertBefore(box, list);
  box.querySelector('input').addEventListener('input', (e) => { _officeSearch[key] = e.target.value; redraw(); });
}

async function renderOfficeRequests(office, cached) {
  const list = document.getElementById('office-requests-list');
  let active;
  if (cached && _officeReqCache) {
    active = _officeReqCache;
  } else {
    showSkeleton(list, 3);
    // تُستبعد طلبات أي رحلة أُلغيت بالكامل من قائمة الطلبات النشطة (حُذفت "من خانة الطلبات")
    const allBookings = await UbourDB.getBookingsForOffice(office.id);
    const bookings = allBookings.filter(b => b.trips && b.trips.office_id === office.id);
    const tripsMap = await UbourDB.getTripsByIds(bookings.map((b) => b.trip_id));
    const withTrips = bookings.map((b) => ({ b, trip: tripsMap[b.trip_id] || null }));
    active = withTrips.filter(({ trip }) => trip && trip.status !== 'cancelled' && !isPastRetention(trip));
    _officeReqCache = active;
  }

  if (!active.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.bell}<div class="mt-2">لا توجد طلبات حجز واردة بعد</div></div>`;
    return;
  }
  ensureOfficeSearch(list, 'requests', 'ابحث: اسم المسافر أو رقمه أو الوجهة', () => renderOfficeRequests(office, true));
  const rq = _norm(_officeSearch.requests).trim();
  const shownReq = rq ? active.filter(({ b, trip }) => _norm([b.traveler_name, b.traveler_phone, trip.from_place, trip.to_place].join(' ')).includes(rq)) : active;
  if (!shownReq.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.bell}<div class="mt-2">لا توجد نتائج مطابقة</div></div>`;
    return;
  }
  const byId = {};
  active.forEach((x) => { byId[x.b.id] = x; });

  list.innerHTML = shownReq.slice().reverse().map(({ b, trip }) => {
    const badge = bookingBadge(b, 'office');
    const pending = b.status === 'pending';
    const confirmed = b.status === 'completed';
    const cancelled = b.status === 'cancel_requested';
    const who = b.cancelled_by === 'office' ? 'من طرفك' : 'من المسافر';
    return `
      <div class="list-card">
        <div class="lc-top">
          <div>
            <span class="lc-title">${esc(b.traveler_name)}</span>
            <div class="lc-sub"><bdi dir="ltr">${esc(b.traveler_phone)}</bdi></div>
          </div>
          <span class="badge-pill ${badge.cls}">${esc(badge.text)}</span>
        </div>
        <div class="lc-route">${ICONS.route}<span>${esc(trip.from_place)}</span>${ICONS.chevron}<span>${esc(trip.to_place)}</span></div>
        ${tripTimesHtml(trip)}
        <div class="lc-meta"><span>${esc(b.seats)} مقعد</span>${trip.vehicle_type ? `<span>${ICONS.bus} ${esc(trip.vehicle_type)}</span>` : ''}</div>
        ${b.ready_at && !cancelled ? '<div class="remind-box ok">✅ المسافر أكّد جاهزيته للرحلة</div>' : ''}
        ${cancelled && b.cancel_reason ? `<div class="lc-sub" style="color:var(--error); margin-bottom:10px;">سبب الإلغاء (${who}): ${esc(b.cancel_reason)}</div>` : ''}
        <div class="lc-actions lc-actions-wrap">
          ${pending ? `<div class="confirm-split"><button type="button" class="act-btn act-wa" data-confirm-booking="${esc(b.id)}">${ICONS.whatsapp}تأكيد عبر واتساب</button><button type="button" class="act-direct" data-direct-confirm="${esc(b.id)}" aria-label="تأكيد مباشر من التطبيق" title="تأكيد مباشر من التطبيق">✅</button></div><button type="button" class="act-btn act-reject" data-reject-booking="${esc(b.id)}">❌ عدم تأكيد</button>` : ''}
          ${confirmed ? `<button type="button" class="act-btn act-reject" data-cancel-confirmed="${esc(b.id)}">إلغاء الحجز المؤكَّد</button>` : ''}
          ${!cancelled ? `<button type="button" class="whatsapp-btn" data-wa-booking="${esc(b.id)}">${ICONS.whatsapp}واتساب</button>` : ''}
        </div>
      </div>`;
  }).join('');

  // تواصل فقط (يُرسَل من هاتف المكتب/السائق نفسه إلى رقم المسافر) — لا يغيّر حالة الحجز
  list.querySelectorAll('[data-wa-booking]').forEach(btn => {
    btn.addEventListener('click', () => {
      const x = byId[btn.dataset.waBooking];
      if (!x) return;
      const msg = `مرحباً ${x.b.traveler_name}، معك ${office.name} بخصوص حجزك لرحلة ${x.trip.from_place} ← ${x.trip.to_place} يوم ${fmtDateAr(x.trip.trip_date)} الساعة ${fmtTime12(x.trip.trip_time)}.`;
      openExternal(whatsappLink(x.b.traveler_phone, msg));
    });
  });

  // تأكيد: نسجّل الحالة في القاعدة أولاً، ثم تُفتح رسالة التأكيد من هاتف المكتب/السائق إلى المسافر
  list.querySelectorAll('[data-confirm-booking]').forEach(btn => {
    btn.addEventListener('click', async () => {
      const x = byId[btn.dataset.confirmBooking];
      if (!x || btn.disabled) return;
      btn.disabled = true;
      try { await UbourDB.updateBookingStatus(x.b.id, 'completed'); }
      catch (e) { showToast(bookingErrorMessage(e), 'error', 5000); console.error(e); await renderOfficeRequests(office); return; }
      const nums = officeContactNumbers(office);
      const msg = `مرحباً ${x.b.traveler_name} 👋\nيسرّنا تأكيد حجزك مع ${office.name} ✅\n` +
        `الرحلة: ${x.trip.from_place} ← ${x.trip.to_place}\n` +
        `التحرك: ${fmtDateAr(x.trip.trip_date)} الساعة ${fmtTime12(x.trip.trip_time)}\n` +
        (x.trip.checkin_time ? `الحضور المطلوب: ${fmtTime12(x.trip.checkin_time)}\n` : '') +
        `عدد المقاعد: ${x.b.seats}\n` +
        (office.address ? `موقعنا: ${office.address}\n` : '') +
        (nums.length ? `للتواصل: ${nums.join(' / ')}\n` : '') +
        `نتمنى لك رحلة سعيدة 🌟`;
      openExternal(whatsappLink(x.b.traveler_phone, msg));
      showToast('تم تأكيد الحجز', 'success');
      await renderOfficeRequests(office);
    });
  });
  list.querySelectorAll('[data-reject-booking]').forEach(btn => {
    btn.addEventListener('click', () => openCancelModal(btn.dataset.rejectBooking, 'office', 'booking', 'reject'));
  });
  list.querySelectorAll('[data-cancel-confirmed]').forEach(btn => {
    btn.addEventListener('click', () => openCancelModal(btn.dataset.cancelConfirmed, 'office', 'booking', 'cancel-confirmed'));
  });
  list.querySelectorAll('[data-direct-confirm]').forEach(btn => {
    btn.addEventListener('click', () => { const x = byId[btn.dataset.directConfirm]; if (x) openDirectConfirm(x); });
  });
}

function tripStatusLabel(status) {
  return { active: 'نشطة', inactive: 'غير نشطة', cancelled: 'ملغاة' }[status] || status;
}
async function renderOfficeTrips(office, cached) {
  const list = document.getElementById('office-trips-list');
  let trips;
  if (cached && _officeTripsCache) {
    trips = _officeTripsCache;
  } else {
    showSkeleton(list, 3);
    trips = (await UbourDB.getTripsByOffice(office.id)).filter(t => !isPastRetention(t));
    _officeTripsCache = trips;
  }
  if (!trips.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.route}<div class="mt-2">لم تُضِف أي رحلة بعد</div></div>`;
    return;
  }
  ensureOfficeSearch(list, 'trips', 'ابحث: من / إلى / نوع المركبة / التاريخ', () => renderOfficeTrips(office, true));
  const tq = _norm(_officeSearch.trips).trim();
  const shownTrips = tq ? trips.filter(t => _norm([t.from_place, t.to_place, t.vehicle_type, t.trip_date, fmtDateAr(t.trip_date)].join(' ')).includes(tq)) : trips;
  if (!shownTrips.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.route}<div class="mt-2">لا توجد نتائج مطابقة</div></div>`;
    return;
  }
  list.innerHTML = shownTrips.slice().reverse().map(t => `
    <div class="list-card">
      <div class="lc-top">
        <span class="badge-pill status-${t.status === 'active' ? 'active' : t.status === 'cancelled' ? 'cancel_requested' : 'inactive'}">${tripStatusLabel(t.status)}</span>
        <span class="lc-price">${esc(t.price)} ${currencyLabel(t.currency)}</span>
      </div>
      <div class="lc-route">${ICONS.route}<span>${esc(t.from_place)}</span>${ICONS.chevron}<span>${esc(t.to_place)}</span></div>
      ${officePromoNoteHtml(t)}
      ${tripTimesHtml(t)}
      ${tcExtraHtml(t)}
      <div class="lc-meta"><span>${esc(t.seats_available)}/${esc(t.seats_total)} مقعد متاح</span>${t.vehicle_type ? `<span>${ICONS.bus} ${esc(t.vehicle_type)}</span>` : ''}${t.accepts_parcels ? '<span>📦 طرود</span>' : ''}${isPromoted(t) ? '<span>⭐ مميّزة حتى ' + esc(fmtDMYHM(t.promoted_until)) + '</span>' : ''}</div>
      ${t.status === 'cancelled' && t.cancel_reason ? `<div class="lc-sub" style="color:var(--error); margin-bottom:10px;">سبب الإلغاء: ${esc(t.cancel_reason)}</div>` : ''}
      <div class="lc-actions">
        ${t.status !== 'cancelled' ? `<button class="btn btn-ghost" data-edit-trip="${esc(t.id)}" style="padding:11px; font-size:13px; flex:1;">تعديل</button>` : ''}
        ${t.status === 'active' ? `<button class="btn btn-ghost" data-cancel-trip="${esc(t.id)}" style="padding:11px; font-size:13px; flex:1;">إلغاء الرحلة</button>` : ''}
        ${t.status === 'active' ? `<button type="button" class="share-btn" data-share-trip="${esc(t.id)}" aria-label="مشاركة الرحلة">${ICONS.share}</button>` : ''}
        <button class="icon-action-btn" data-delete-trip="${esc(t.id)}">${ICONS.trash}</button>
      </div>
    </div>
  `).join('');
  list.querySelectorAll('[data-delete-trip]').forEach(btn => {
    btn.addEventListener('click', async () => {
      await UbourDB.deleteTrip(btn.dataset.deleteTrip);
      await renderOfficeTrips(office);
      showToast('تم حذف الرحلة', 'info');
    });
  });
  list.querySelectorAll('[data-cancel-trip]').forEach(btn => {
    btn.addEventListener('click', () => openCancelModal(btn.dataset.cancelTrip, 'office', 'trip'));
  });
  list.querySelectorAll('[data-edit-trip]').forEach(btn => {
    btn.addEventListener('click', () => openEditTripModal(trips.find(x => x.id === btn.dataset.editTrip)));
  });
  list.querySelectorAll('[data-share-trip]').forEach(btn => {
    btn.addEventListener('click', () => { const t = trips.find(x => x.id === btn.dataset.shareTrip); if (t) shareTrip(t, office.name); });
  });
}

/* ---- تعديل رحلة (للمكتب/السائق صاحب الرحلة فقط — تفرضه قاعدة البيانات أيضاً عبر RLS) ---- */
let _editingTrip = null;
const _TRIP_FIELD_IDS = ['input-trip-from', 'input-trip-to', 'input-trip-vehicle', 'input-trip-price', 'input-trip-seats', 'input-trip-date', 'input-trip-time', 'input-trip-checkin', 'input-trip-title', 'input-trip-route', 'input-trip-amenities'];
function updateTripTimePreviews() {
  const t = document.getElementById('input-trip-time').value, c = document.getElementById('input-trip-checkin').value;
  const pt = document.getElementById('preview-trip-time'), pc = document.getElementById('preview-trip-checkin');
  if (pt) pt.textContent = t ? 'سيظهر للمسافرين: ' + fmtTime12(t) : '';
  if (pc) pc.textContent = c ? 'سيظهر للمسافرين: ' + fmtTime12(c) : '';
}
function _setTripModalMode(editing) {
  document.getElementById('add-trip-title').textContent = editing ? 'تعديل الرحلة' : 'إضافة رحلة جديدة';
  document.getElementById('add-trip-btn-label').textContent = editing ? 'حفظ التعديلات' : 'نشر الرحلة';
  document.getElementById('error-add-trip').classList.remove('show');
}
function openEditTripModal(trip) {
  if (!trip) return;
  _editingTrip = trip;
  _setTripModalMode(true);
  document.getElementById('input-trip-from').value = trip.from_place || '';
  document.getElementById('input-trip-to').value = trip.to_place || '';
  document.getElementById('input-trip-vehicle').value = trip.vehicle_type || '';
  document.getElementById('input-trip-price').value = trip.price;
  document.getElementById('select-trip-currency').value = trip.currency;
  document.getElementById('input-trip-seats').value = trip.seats_total;
  document.getElementById('input-trip-date').value = trip.trip_date;
  document.getElementById('input-trip-time').value = String(trip.trip_time || '').slice(0, 5);
  document.getElementById('input-trip-checkin').value = String(trip.checkin_time || '').slice(0, 5);
  document.getElementById('input-trip-parcels').checked = !!trip.accepts_parcels;
  document.getElementById('input-trip-parcels-note').value = trip.parcels_note || '';
  document.getElementById('input-trip-title').value = trip.trip_title || '';
  document.getElementById('input-trip-route').value = trip.route_details || '';
  document.getElementById('input-trip-amenities').value = trip.amenities || '';
  syncAmenityPicks();
  document.getElementById('wrap-trip-parcels-note').classList.toggle('hidden', !trip.accepts_parcels);
  updateTripTimePreviews();
  document.getElementById('modal-add-trip').classList.add('active');
}

function initOfficeScreen() {
  document.querySelectorAll('#screen-office .nav-item').forEach(item => {
    item.addEventListener('click', () => {
      document.querySelectorAll('#screen-office .nav-item').forEach(n => n.classList.remove('active'));
      item.classList.add('active');
      document.querySelectorAll('#screen-office .home-view').forEach(v => v.classList.add('hidden'));
      document.getElementById('office-view-' + item.dataset.officeTab).classList.remove('hidden');
      if (item.dataset.officeTab === 'profile' && _currentProfileCache) renderOfficeStats(_currentProfileCache);
    });
  });

  document.getElementById('btn-office-logout').addEventListener('click', doLogout);

  // طلب تجديد الاشتراك عبر واتساب — يتواصل مباشرة مع المدير الرئيسي؛
  // التجديد الفعلي وتحديد التواريخ يبقى بيد المدير حصرياً من لوحة الإدارة
  document.getElementById('btn-request-subscription').addEventListener('click', async () => {
    const primaryPhone = await UbourDB.getPrimaryManagerPhone();
    if (!primaryPhone) { showToast('تعذّر العثور على رقم الإدارة حالياً', 'error'); return; }
    const office = await UbourDB.getCurrentProfile();
    const msg = `مرحباً، أرغب بتجديد اشتراك حسابي "${office ? office.name : ''}" في ${APP_CONFIG.nameShort}.`;
    openExternal(whatsappLink(primaryPhone, msg));
  });

  // اقتراحات المدن/المناطق عبر datalist — لكن الحقل نص حر يقبل أي منطقة يكتبها
  // صاحب المكتب يدوياً حتى لو لم تكن ضمن القائمة (كما طُلب)
  const allPlaces = [...APP_CONFIG.yemenGovernorates, ...APP_CONFIG.saudiCities];
  document.getElementById('datalist-places').innerHTML = allPlaces.map(p => `<option value="${p}"></option>`).join('');
  document.getElementById('select-trip-currency').innerHTML = APP_CONFIG.currencies.map(c => `<option value="${c.code}">${c.label}</option>`).join('');
  document.getElementById('datalist-vehicle-types').innerHTML = APP_CONFIG.vehicleTypes.map(v => `<option value="${v}"></option>`).join('');

  ['input-trip-time', 'input-trip-checkin'].forEach((id) => {
    const inp = document.getElementById(id);
    ['input', 'change'].forEach((ev) => inp.addEventListener(ev, updateTripTimePreviews));
  });

  document.getElementById('btn-open-add-trip').addEventListener('click', () => {
    const me = _currentProfileCache;
    if (me && (me.is_disabled || !(me.subscription_active && UbourDB.daysRemaining(me) > 0))) {
      showToast(me.is_disabled ? 'حسابك معطّل — يرجى مراجعة الإدارة' : 'انتهى اشتراكك — يرجى تجديد الاشتراك بمراجعة الإدارة', 'error', 6000);
      return;
    }
    _editingTrip = null;
    _setTripModalMode(false);
    _TRIP_FIELD_IDS.forEach(id => document.getElementById(id).value = '');
    document.getElementById('input-trip-parcels').checked = false;
    document.getElementById('input-trip-parcels-note').value = '';
    document.getElementById('wrap-trip-parcels-note').classList.add('hidden');
    updateTripTimePreviews();
    syncAmenityPicks();
    document.getElementById('modal-add-trip').classList.add('active');
  });

  document.getElementById('btn-submit-add-trip').addEventListener('click', async () => {
    const from = document.getElementById('input-trip-from').value.trim();
    const to = document.getElementById('input-trip-to').value.trim();
    const vehicleType = document.getElementById('input-trip-vehicle').value.trim();
    const price = normalizeDigits(document.getElementById('input-trip-price').value).trim();
    const currency = document.getElementById('select-trip-currency').value;
    const seats = normalizeDigits(document.getElementById('input-trip-seats').value).trim();
    const date = document.getElementById('input-trip-date').value;
    const time = document.getElementById('input-trip-time').value;
    const checkin = document.getElementById('input-trip-checkin').value;
    const parcels = !!document.getElementById('input-trip-parcels').checked;
    const parcelsNote = document.getElementById('input-trip-parcels-note').value.trim().slice(0, 120);
    const tripTitle = document.getElementById('input-trip-title').value.trim().slice(0, 40);
    const routeDetails = document.getElementById('input-trip-route').value.trim().slice(0, 160);
    const amenities = document.getElementById('input-trip-amenities').value.trim().slice(0, 160);
    const errorEl = document.getElementById('error-add-trip');
    errorEl.classList.remove('show');

    if (!from || !to) { errorEl.textContent = 'يرجى تحديد نقطتي الانطلاق والوصول'; errorEl.classList.add('show'); return; }
    if (from === to) { errorEl.textContent = 'يجب أن تختلف نقطة الانطلاق عن الوصول'; errorEl.classList.add('show'); return; }
    if (!price || !seats || !date || !time) { errorEl.textContent = 'يرجى تعبئة جميع الحقول'; errorEl.classList.add('show'); return; }
    if (!/^\d+(\.\d{1,2})?$/.test(price) || !/^\d+$/.test(seats) || !(Number(price) > 0) || !(Number(seats) > 0)) { errorEl.textContent = 'يرجى إدخال قيم صحيحة للسعر وعدد المقاعد'; errorEl.classList.add('show'); return; }
    if (checkin) {
      const gap = checkinGapHours(checkin, time);
      if (gap === null || gap > 12) { errorEl.textContent = 'وقت الحضور يجب أن يسبق وقت التحرك بما لا يزيد عن 12 ساعة'; errorEl.classList.add('show'); return; }
    }
    if (!_editingTrip && !(tripDepartureMs({ trip_date: date, trip_time: time }) > Date.now())) {
      errorEl.textContent = 'موعد التحرك يجب أن يكون في المستقبل — تحقق من التاريخ والوقت (صباحاً/مساءً)';
      errorEl.classList.add('show'); return;
    }

    const office = await UbourDB.getCurrentProfile();
    if (!office) return;

    // وضع التعديل: تحديث الرحلة الحالية بدل إنشاء رحلة جديدة
    if (_editingTrip) {
      const booked = Number(_editingTrip.seats_total) - Number(_editingTrip.seats_available);
      if (Number(seats) < booked) {
        errorEl.textContent = 'لا يمكن أن يقل عدد المقاعد عن المقاعد المحجوزة حالياً (' + booked + ')';
        errorEl.classList.add('show');
        return;
      }
      try {
        await UbourDB.updateTrip(_editingTrip.id, {
          from_place: from, to_place: to, vehicle_type: vehicleType || null,
          price: Number(price), currency,
          seats_total: Number(seats), seats_available: Number(seats) - booked,
          trip_date: date, trip_time: time,
          ...((checkin || ('checkin_time' in _editingTrip)) ? { checkin_time: checkin || null } : {}),
          ...(('accepts_parcels' in _editingTrip) ? { accepts_parcels: parcels, parcels_note: parcels ? (parcelsNote || null) : null } : {}),
          ...((('trip_title' in _editingTrip) || tripTitle || routeDetails || amenities) ? { trip_title: tripTitle || null, route_details: routeDetails || null, amenities: amenities || null } : {})
        });
        _editingTrip = null;
        closeModals();
        await renderOfficeTrips(office);
        showToast(booked > 0 ? 'تم تحديث الرحلة — لديك حجوزات عليها، يُفضّل إبلاغ المسافرين بالتعديل' : 'تم تحديث الرحلة بنجاح', 'success');
      } catch (e) {
        showToast('تعذّر حفظ التعديلات، حاول مجدداً', 'error');
        console.error(e);
      }
      return;
    }

    try {
      await UbourDB.createTrip({ officeId: office.id, officeName: office.name, from, to, price, currency, seatsTotal: seats, date, time, vehicleType, checkin, parcels, parcelsNote, tripTitle, routeDetails, amenities });
      closeModals();
      await renderOfficeTrips(office);
      showToast('تم نشر الرحلة بنجاح', 'success');
      ['input-trip-from', 'input-trip-to', 'input-trip-vehicle', 'input-trip-price', 'input-trip-seats', 'input-trip-date', 'input-trip-time', 'input-trip-checkin', 'input-trip-title', 'input-trip-route', 'input-trip-amenities'].forEach(id => document.getElementById(id).value = '');
      syncAmenityPicks();
      updateTripTimePreviews();
    } catch (e) {
      showToast((e && (e.code === '42501' || /row-level security/i.test(String(e.message || '')))) ? 'اشتراكك منتهٍ أو غير مفعّل — تواصل مع الإدارة للتجديد' : 'تعذّر نشر الرحلة، حاول مجدداً', 'error');
      console.error(e);
    }
  });

  // اختيار شعار من ملفات الجهاز مباشرة (بدل كتابة رابط) — يُصغَّر تلقائياً
  // ليبقى حجمه معقولاً قبل حفظه، ويُعرض كمعاينة فورية
  let _pendingLogoDataUrl = null;
  document.getElementById('btn-pick-office-logo').addEventListener('click', () => {
    document.getElementById('input-office-logo-file').click();
  });
  document.getElementById('input-office-logo-file').addEventListener('change', (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) { showToast('يرجى اختيار ملف صورة', 'error'); return; }

    const reader = new FileReader();
    reader.onload = (ev) => {
      const img = new Image();
      img.onload = () => {
        const maxDim = 480;
        let w = img.width, h = img.height;
        if (w > h && w > maxDim) { h = Math.round(h * maxDim / w); w = maxDim; }
        else if (h > maxDim) { w = Math.round(w * maxDim / h); h = maxDim; }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        _pendingLogoDataUrl = canvas.toDataURL('image/jpeg', 0.85);

        const preview = document.getElementById('office-logo-preview');
        preview.src = _pendingLogoDataUrl;
        preview.classList.remove('hidden');
        document.getElementById('office-logo-picker-placeholder').classList.add('hidden');
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  });

  // حفظ اسم/شعار المكتب أو السائق — قابل للتعديل في أي وقت كما طُلب
  document.getElementById('btn-save-office-profile').addEventListener('click', async () => {
    const office = await UbourDB.getCurrentProfile();
    if (!office) return;
    const name = document.getElementById('input-office-edit-name').value.trim();
    if (!name) { showToast('يرجى إدخال الاسم', 'error'); return; }
    const location = document.getElementById('input-office-edit-location').value.trim();
    const p1 = document.getElementById('input-office-edit-phone1').value.trim();
    const p2 = document.getElementById('input-office-edit-phone2').value.trim();
    let c1 = null, c2 = null;
    if (p1) { const r1 = UbourAuth.detectPhone(p1); if (!r1.valid) { showToast('رقم التواصل الأول غير صحيح (يمني 7xxxxxxxx أو سعودي 05xxxxxxxx)', 'error', 5000); return; } c1 = r1.e164; }
    if (p2) { const r2 = UbourAuth.detectPhone(p2); if (!r2.valid) { showToast('رقم التواصل الثاني غير صحيح (يمني 7xxxxxxxx أو سعودي 05xxxxxxxx)', 'error', 5000); return; } c2 = r2.e164; }
    const patch = { name, address: location || null, contact_phone: c1, contact_phone2: c2 };
    // ملاحظة هامة: صورة الشعار محفوظة هنا كنص Base64 طويل مباشرة في عمود
    // logo_url (كما كانت في النسخة التجريبية السابقة). هذا يعمل، لكن الأصح
    // للإنتاج الحقيقي رفعها كملف إلى Supabase Storage وحفظ رابط قصير فقط —
    // خطوة تحسين لاحقة، وليست عائقاً أمام عمل الميزة الآن.
    if (_pendingLogoDataUrl) patch.logo_url = _pendingLogoDataUrl;
    try {
      const updated = await UbourDB.updateOffice(office.id, patch);
      document.getElementById('office-user-name').textContent = name;
      renderOfficeAvatar(updated);
      renderOfficeContactRows(updated);
      document.getElementById('input-office-edit-phone1').value = updated.contact_phone || '';
      document.getElementById('input-office-edit-phone2').value = updated.contact_phone2 || '';
      _currentProfileCache = updated;
      _pendingLogoDataUrl = null;
      showToast('تم حفظ التعديلات', 'success');
    } catch (e) {
      showToast('تعذّر حفظ التعديلات', 'error');
      console.error(e);
    }
  });

  // إرسال رسالة دعم فني من المكتب/السائق
  document.getElementById('btn-office-support-send').addEventListener('click', async () => {
    const msgInput = document.getElementById('input-office-support-message');
    const msg = msgInput.value.trim();
    if (!msg) { showToast('اكتب رسالتك أولاً', 'error'); return; }
    const office = await UbourDB.getCurrentProfile();
    if (!office) return;
    await UbourDB.createSupportMessage({ fromId: office.id, fromName: office.name || office.phone, fromPhone: office.phone, message: msg });
    msgInput.value = '';
    showToast('تم إرسال رسالتك للدعم الفني', 'success');
  });
}

